/**
 * `/ws/chat` realtime gateway.
 *
 * Sockets subscribe to channels they may read; delivery is driven by the Redis
 * `message.created` event, so every chat-service instance broadcasts to its own
 * sockets and horizontal scaling needs no sticky sessions.
 */
import { Injectable, OnModuleDestroy } from '@nestjs/common';
import type { Server as HttpServer } from 'node:http';
import { WebSocket, WebSocketServer } from 'ws';
import { prisma } from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import { PERMISSIONS } from '@betweenus/permissions';
import {
  CONTROL_MAX_PAYLOAD,
  RoomRegistry,
  authenticateHandshake,
  channelRoom,
  dropRevokedSockets,
  serverRoom,
  userRoom,
} from '@betweenus/websocket';
import { Logger } from '@betweenus/logger';
import type { ClientChatEvent, ServerChatEvent, UserSummary } from '@betweenus/shared-types';
import { MessagesService } from '../modules/messages/messages.service';

const HEARTBEAT_INTERVAL_MS = 30_000;

interface SocketState {
  userId: string;
  username: string;
  alive: boolean;
  /** `iat` of the token that opened this socket. See `dropRevokedSockets`. */
  issuedAt: number;
}

@Injectable()
export class ChatGateway implements OnModuleDestroy {
  private server: WebSocketServer | null = null;
  private heartbeat: NodeJS.Timeout | null = null;
  private readonly rooms = new RoomRegistry<WebSocket>();
  private readonly state = new WeakMap<WebSocket, SocketState>();

  constructor(
    private readonly messages: MessagesService,
    private readonly events: EventBus,
    private readonly logger: Logger,
  ) {}

  /**
   * Every socket this instance holds for one account.
   *
   * Scanned rather than looked up in a room, because the four gateways keep
   * different bookkeeping and `clients` is the one thing all of them have. A
   * revocation is rare; a scan of the sockets on one instance is nothing.
   */
  private socketsOf(userId: string): WebSocket[] {
    return [...(this.server?.clients ?? [])].filter(
      (socket) => this.state.get(socket)?.userId === userId,
    );
  }

  /** Called from main.ts once Nest owns a listening HTTP server. */
  async attach(httpServer: HttpServer): Promise<void> {
    this.server = new WebSocketServer({
      server: httpServer,
      path: '/ws/chat',
      maxPayload: CONTROL_MAX_PAYLOAD,
    });

    this.server.on('connection', (socket, request) => {
      const user = authenticateHandshake(request);
      if (!user) {
        // Never downgrade to anonymous: close with a policy-violation code.
        socket.close(4401, 'Unauthorized');
        return;
      }

      this.state.set(socket, {
        userId: user.id,
        username: user.username,
        alive: true,
        issuedAt: user.issuedAt,
      });
      // Everything addressed at a person rather than a place - a friend
      // request, an acceptance, being added to a server - is delivered here.
      this.rooms.join(userRoom(user.id), socket);
      this.send(socket, { type: 'ready', userId: user.id });
      this.logger.info('WebSocket connected', { userId: user.id });

      socket.on('pong', () => {
        const state = this.state.get(socket);
        if (state) state.alive = true;
      });

      socket.on('message', (raw) => {
        void this.handleClientEvent(socket, raw.toString());
      });

      socket.on('close', () => {
        this.rooms.leaveAll(socket);
        this.state.delete(socket);
        this.logger.info('WebSocket disconnected', { userId: user.id });
      });

      socket.on('error', (error) => {
        this.logger.warn('WebSocket error', { userId: user.id, reason: String(error) });
      });
    });

    // Drop sockets that stopped answering pings instead of leaking them.
    this.heartbeat = setInterval(() => {
      for (const socket of this.server?.clients ?? []) {
        const state = this.state.get(socket);
        if (!state) continue;
        if (!state.alive) {
          socket.terminate();
          continue;
        }
        state.alive = false;
        socket.ping();
      }
    }, HEARTBEAT_INTERVAL_MS);

    // An account whose authority was withdrawn loses the sockets it already
    // had, which is the half of a revocation that was missing: a handshake is
    // checked once and then trusted until it happens to disconnect.
    await dropRevokedSockets(
      this.events,
      (userId) => this.socketsOf(userId),
      (socket) => this.state.get(socket)?.issuedAt,
      (socket, code, reason) => socket.close(code, reason),
      (userId, count, reason) =>
        this.logger.info('Sockets revoked', { userId, count, reason }),
    );

    await this.events.subscribe(EVENTS.MESSAGE_CREATED, (envelope) => {
      const { message } = envelope.payload;
      this.broadcast(channelRoom(message.channelId), { type: 'message.created', message });
    });

    // An edit, a pin, a reaction and a deletion all reach the client as the
    // same event carrying the whole message - a deleted one is a tombstone with
    // `deletedAt` set, which is what the client has to draw.
    await this.events.subscribe(EVENTS.MESSAGE_UPDATED, (envelope) => {
      const { message } = envelope.payload;
      this.broadcast(channelRoom(message.channelId), { type: 'message.updated', message });
    });

    // Except when there is no tombstone. A one-time message that was opened,
    // and one whose disappearing window closed, are destroyed rather than
    // emptied - so what goes out is "forget this", not a message to redraw.
    await this.events.subscribe(EVENTS.MESSAGE_DELETED, (envelope) => {
      const { message, messageId, channelId } = envelope.payload;
      this.broadcast(
        channelRoom(channelId),
        message
          ? { type: 'message.updated', message }
          : { type: 'message.gone', messageId, channelId },
      );
    });

    // A read marker moved. Everyone subscribed to the channel is told, because
    // a read receipt is only useful to the person whose message was read - and
    // the marker is what every client derives "who has seen this" from.
    await this.events.subscribe(EVENTS.CHANNEL_READ, (envelope) => {
      const { channelId, userId, at } = envelope.payload;
      this.broadcast(channelRoom(channelId), { type: 'channel.read', channelId, userId, at });
    });

    // Somebody cleared their own history. It goes to that account's room and
    // nowhere else: every other participant's copy is exactly what it was, and
    // the only sockets that have anything to do are the ones holding this
    // account's own decrypted cache.
    await this.events.subscribe(EVENTS.CHATS_CLEARED, (envelope) => {
      const { userId, clearedAt, channelId } = envelope.payload;
      this.broadcast(userRoom(userId), { type: 'chats.cleared', clearedAt, channelId });
    });

    await this.events.subscribe(EVENTS.FRIEND_CHANGED, (envelope) => {
      for (const userId of envelope.payload.userIds) {
        this.broadcast(userRoom(userId), { type: 'friends.changed' });
      }
    });

    // Somebody posted, deleted, or aged out of a status. The audience was
    // worked out where the row was written - that is where the friend list
    // already was - so this only has to deliver it.
    await this.events.subscribe(EVENTS.STATUS_CHANGED, (envelope) => {
      const { userIds, authorId } = envelope.payload;
      this.deliver(userIds.map(userRoom), { type: 'status.changed', authorId });
    });

    // Every membership change reaches the same client event: the server's
    // watchers refresh their member list, and the person who joined, was
    // removed or had their permissions changed refreshes their own list of
    // servers - which is where the permissions their UI reads come from.
    for (const event of [
      EVENTS.SERVER_MEMBER_ADDED,
      EVENTS.SERVER_MEMBER_REMOVED,
      EVENTS.SERVER_MEMBER_UPDATED,
    ] as const) {
      await this.events.subscribe(event, (envelope) => {
        const { serverId, userId } = envelope.payload;
        this.deliver([serverRoom(serverId), userRoom(userId)], {
          type: 'server.members.changed',
          serverId,
        });
      });
    }

    // A renamed server, or one with a new picture. Everyone watching it is
    // holding the old one in a sidebar.
    await this.events.subscribe(EVENTS.SERVER_UPDATED, (envelope) => {
      const { serverId, name, iconUrl } = envelope.payload;
      this.broadcast(serverRoom(serverId), { type: 'server.updated', serverId, name, iconUrl });
    });

    // A changed profile has to reach everyone who draws it, which is a wider
    // set than any one room: the members of every server this account is in,
    // everyone it is friends with, and its own other devices.
    await this.events.subscribe(EVENTS.USER_UPDATED, (envelope) => {
      void this.broadcastProfile(envelope.payload.user);
    });

    this.logger.info('Chat WebSocket gateway ready', { path: '/ws/chat' });
  }

  private async handleClientEvent(socket: WebSocket, raw: string): Promise<void> {
    const state = this.state.get(socket);
    if (!state) return;

    let event: ClientChatEvent;
    try {
      event = JSON.parse(raw) as ClientChatEvent;
    } catch {
      this.send(socket, { type: 'error', code: 'BAD_PAYLOAD', message: 'Malformed JSON' });
      return;
    }

    switch (event.type) {
      case 'ping':
        this.send(socket, { type: 'pong' });
        return;

      case 'channel.subscribe':
        try {
          // Re-check on every subscribe: permissions can change mid-session.
          await this.messages.requireChannelAccess(
            state.userId,
            event.channelId,
            PERMISSIONS.VIEW_CHANNEL,
          );
        } catch {
          this.send(socket, {
            type: 'error',
            code: 'CHANNEL_FORBIDDEN',
            message: 'Cannot subscribe to this channel',
          });
          return;
        }
        this.rooms.join(channelRoom(event.channelId), socket);
        return;

      case 'channel.unsubscribe':
        this.rooms.leave(channelRoom(event.channelId), socket);
        return;

      case 'server.subscribe': {
        // Membership, not permission: anyone in the server may know when its
        // member list changes, which is what the client re-reads.
        const membership = await prisma.serverMember.findUnique({
          where: { serverId_userId: { serverId: event.serverId, userId: state.userId } },
          select: { id: true },
        });
        if (!membership) {
          this.send(socket, {
            type: 'error',
            code: 'SERVER_FORBIDDEN',
            message: 'Cannot subscribe to this server',
          });
          return;
        }
        this.rooms.join(serverRoom(event.serverId), socket);
        return;
      }

      case 'server.unsubscribe':
        this.rooms.leave(serverRoom(event.serverId), socket);
        return;

      default:
        this.send(socket, { type: 'error', code: 'UNKNOWN_EVENT', message: 'Unsupported event' });
    }
  }

  /**
   * Who can see a profile: every server they share, plus every friendship.
   *
   * Friendships rather than DM channels because a direct message already
   * requires an accepted friendship - so the friend list is the same set, and
   * it is one query rather than two.
   */
  private async broadcastProfile(user: UserSummary): Promise<void> {
    const [memberships, friendships] = await Promise.all([
      prisma.serverMember.findMany({ where: { userId: user.id }, select: { serverId: true } }),
      prisma.friendship.findMany({
        where: { status: 'ACCEPTED', OR: [{ userAId: user.id }, { userBId: user.id }] },
        select: { userAId: true, userBId: true },
      }),
    ]);

    const rooms = [
      userRoom(user.id),
      ...memberships.map((row) => serverRoom(row.serverId)),
      ...friendships.map((row) => userRoom(row.userAId === user.id ? row.userBId : row.userAId)),
    ];
    this.deliver(rooms, { type: 'user.updated', user });
  }

  private broadcast(room: string, event: ServerChatEvent): void {
    for (const socket of this.rooms.members(room)) this.send(socket, event);
  }

  /** Several rooms, one delivery each - a socket in two of them is told once. */
  private deliver(rooms: string[], event: ServerChatEvent): void {
    const seen = new Set<WebSocket>();
    for (const room of rooms) {
      for (const socket of this.rooms.members(room)) seen.add(socket);
    }
    for (const socket of seen) this.send(socket, event);
  }

  private send(socket: WebSocket, event: ServerChatEvent): void {
    if (socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify(event));
  }

  onModuleDestroy(): void {
    if (this.heartbeat) clearInterval(this.heartbeat);
    this.server?.close();
  }
}

import {
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  Param,
  ParseUUIDPipe,
  Patch,
  Post,
  Put,
  Query,
  UseGuards,
} from '@nestjs/common';
import { CurrentUser, JwtAuthGuard, type AuthenticatedUser } from '@betweenus/auth';
import type {
  ClearChatsResponse,
  LinkPreview,
  Message,
  Paginated,
} from '@betweenus/shared-types';
import { MessagesService } from './messages.service';
import { UnfurlService } from './unfurl.service';
import {
  ClearChatsDto,
  CreateMessageDto,
  MessageQueryDto,
  PinQueryDto,
  ReactToMessageDto,
  UpdateMessageDto,
} from './dto';

@Controller('messages')
@UseGuards(JwtAuthGuard)
export class MessagesController {
  constructor(
    private readonly messages: MessagesService,
    private readonly unfurlService: UnfurlService,
  ) {}

  @Get()
  history(
    @CurrentUser() user: AuthenticatedUser,
    @Query() query: MessageQueryDto,
  ): Promise<Paginated<Message>> {
    return this.messages.history(user.id, query.channelId, query.before);
  }

  // Ahead of `:messageId` routes, or `unfurl` is read as a message id.
  @Get('unfurl')
  unfurl(@Query('url') targetUrl?: string): Promise<LinkPreview | null> {
    if (!targetUrl) return Promise.resolve(null);
    return this.unfurlService.unfurl(targetUrl);
  }

  // Ahead of `:messageId` routes, or `pins` is read as a message id.
  @Get('pins')
  pins(
    @CurrentUser() user: AuthenticatedUser,
    @Query() query: PinQueryDto,
  ): Promise<Message[]> {
    return this.messages.pins(user.id, query.channelId);
  }

  /**
   * Hides this account's own history: one conversation when `channelId` is
   * given, every one of them when it is not. Ahead of `:messageId`, or `clear`
   * is read as a message id.
   */
  @Post('clear')
  @HttpCode(200)
  clear(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: ClearChatsDto,
  ): Promise<ClearChatsResponse> {
    return this.messages.clearChats(user.id, dto.channelId);
  }

  @Post()
  send(@CurrentUser() user: AuthenticatedUser, @Body() dto: CreateMessageDto): Promise<Message> {
    return this.messages.send(
      user.id,
      dto.channelId,
      dto.content,
      dto.attachmentKeys,
      dto.viewOnce,
    );
  }

  @Patch(':messageId')
  edit(
    @CurrentUser() user: AuthenticatedUser,
    @Param('messageId', ParseUUIDPipe) messageId: string,
    @Body() dto: UpdateMessageDto,
  ): Promise<Message> {
    return this.messages.edit(user.id, messageId, dto.content);
  }

  @Delete(':messageId')
  @HttpCode(204)
  remove(
    @CurrentUser() user: AuthenticatedUser,
    @Param('messageId', ParseUUIDPipe) messageId: string,
  ): Promise<void> {
    return this.messages.remove(user.id, messageId);
  }

  /**
   * Spends a one-time message: the caller has opened its media, so it goes.
   *
   * A POST rather than the DELETE it resembles, because the caller is usually
   * not allowed to delete this message and is not claiming to be - they are
   * reporting that they looked at it, and the destruction is the server's
   * consequence rather than their request. 204 either way: a message already
   * burned by somebody else is not an error to whoever arrived second.
   */
  @Post(':messageId/burn')
  @HttpCode(204)
  burn(
    @CurrentUser() user: AuthenticatedUser,
    @Param('messageId', ParseUUIDPipe) messageId: string,
  ): Promise<void> {
    return this.messages.burn(user.id, messageId);
  }

  @Put(':messageId/pin')
  pin(
    @CurrentUser() user: AuthenticatedUser,
    @Param('messageId', ParseUUIDPipe) messageId: string,
  ): Promise<Message> {
    return this.messages.setPinned(user.id, messageId, true);
  }

  @Delete(':messageId/pin')
  unpin(
    @CurrentUser() user: AuthenticatedUser,
    @Param('messageId', ParseUUIDPipe) messageId: string,
  ): Promise<Message> {
    return this.messages.setPinned(user.id, messageId, false);
  }

  /** One route for both directions: reacting with what you already chose undoes it. */
  @Post(':messageId/reactions')
  react(
    @CurrentUser() user: AuthenticatedUser,
    @Param('messageId', ParseUUIDPipe) messageId: string,
    @Body() dto: ReactToMessageDto,
  ): Promise<Message> {
    return this.messages.react(user.id, messageId, dto.emoji);
  }
}

import {
  BadRequestException,
  Body,
  Controller,
  Delete,
  Get,
  Param,
  ParseUUIDPipe,
  Post,
  Put,
  Query,
  UseGuards,
} from '@nestjs/common';
import { CurrentUser, JwtAuthGuard, type AuthenticatedUser } from '@betweenus/auth';
import type {
  BackupSecretKind,
  ChannelKeysResponse,
  DeviceKey,
  IdentityBackupResponse,
} from '@betweenus/shared-types';
import { E2eeService } from './e2ee.service';
import { PublishChannelKeysDto, PutIdentityBackupDto, RegisterDeviceKeyDto } from './dto';

@Controller('e2ee')
@UseGuards(JwtAuthGuard)
export class E2eeController {
  constructor(private readonly e2ee: E2eeService) {}

  @Post('devices')
  registerDevice(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: RegisterDeviceKeyDto,
  ): Promise<DeviceKey> {
    return this.e2ee.registerDevice(user.id, dto.deviceId, dto.publicKey, dto.label);
  }

  /**
   * This account's own machines. Separate from `GET devices?channelId=`, which
   * answers "whose keys do I wrap for" - this one answers "what is signed in as
   * me", which is a question only the owner gets to ask.
   */
  @Get('devices/mine')
  myDevices(@CurrentUser() user: AuthenticatedUser): Promise<DeviceKey[]> {
    return this.e2ee.myDevices(user.id);
  }

  /** Stops a machine being wrapped for, and deletes what it was already given. */
  @Delete('devices/:deviceId')
  revokeDevice(
    @CurrentUser() user: AuthenticatedUser,
    @Param('deviceId') deviceId: string,
  ): Promise<DeviceKey> {
    return this.e2ee.revokeDevice(user.id, deviceId);
  }

  /**
   * The caller's sealed identity keys, for a machine that has none of its own.
   *
   * Plural: an account may hold a password-sealed blob and a passphrase-sealed
   * one, and a client opens whichever its secret matches.
   */
  @Get('backup')
  backup(@CurrentUser() user: AuthenticatedUser): Promise<IdentityBackupResponse> {
    return this.e2ee.identityBackup(user.id);
  }

  @Put('backup')
  async putBackup(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: PutIdentityBackupDto,
  ): Promise<{ ok: true }> {
    await this.e2ee.putIdentityBackup(user.id, dto);
    return { ok: true };
  }

  /**
   * Removes one kind of backup. What "do not let my account password recover my
   * messages" is made of, once a recovery passphrase is standing.
   */
  @Delete('backup/:kind')
  async deleteBackup(
    @CurrentUser() user: AuthenticatedUser,
    @Param('kind') kind: string,
  ): Promise<{ ok: true }> {
    if (kind !== 'password' && kind !== 'passphrase') {
      throw new BadRequestException({ code: 'INVALID_BACKUP_KIND', message: 'Unknown backup kind' });
    }
    await this.e2ee.deleteIdentityBackup(user.id, kind satisfies BackupSecretKind);
    return { ok: true };
  }

  @Get('devices')
  devices(
    @CurrentUser() user: AuthenticatedUser,
    @Query('channelId', ParseUUIDPipe) channelId: string,
  ): Promise<DeviceKey[]> {
    return this.e2ee.devicesForChannel(user.id, channelId);
  }

  @Get('keys/:channelId')
  keys(
    @CurrentUser() user: AuthenticatedUser,
    @Param('channelId', ParseUUIDPipe) channelId: string,
  ): Promise<ChannelKeysResponse> {
    return this.e2ee.keysForUser(user.id, channelId);
  }

  @Post('keys')
  publish(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: PublishChannelKeysDto,
  ): Promise<{ epoch: number; stored: number }> {
    return this.e2ee.publishKeys(user.id, dto);
  }
}

/**
 * `/ws/call`: the switchboard two clients use to find each other.
 *
 * This gateway introduces peers and then gets out of the way. It knows who is
 * in which channel's call, it forwards an offer, an answer or an ICE candidate
 * from one peer to another, and that is the whole of it. It never sees a frame
 * of media, cannot decode one, and is not in the path where one travels - the
 * peer connections it helps set up run directly between the two machines.
 *
 * That is also why this works through a Cloudflare Tunnel when an SFU did not.
 * Everything crossing this gateway is small, text and reliable, which is what a
 * tunnel carries; the large, continuous, loss-tolerant half never goes near it.
 *
 * Two things it deliberately does not do:
 *
 * - It does not read a signal. `data` is forwarded verbatim, so the SDP a peer
 *   receives is the SDP the other peer wrote. Anything else would put this
 *   service in a position to rewrite a DTLS fingerprint, which is exactly what
 *   the fingerprint signature exists to make useless.
 * - It does not trust `from`. The sender's peer id comes from the socket the
 *   message arrived on, never from the message, so a client cannot sign its
 *   traffic as somebody else.
 */
import { Injectable, OnModuleDestroy } from '@nestjs/common';
import { randomUUID } from 'node:crypto';
import type { Server as HttpServer } from 'node:http';
import { WebSocket, WebSocketServer } from 'ws';
import { resolveChannelAccess } from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import { Logger } from '@betweenus/logger';
import { PERMISSIONS } from '@betweenus/permissions';
import {
  SIGNAL_MAX_PAYLOAD,
  authenticateHandshake,
  dropRevokedSockets,
} from '@betweenus/websocket';
import type {
  CallPeer,
  ClientCallEvent,
  GameSession,
  ListenSession,
  ServerCallEvent,
} from '@betweenus/shared-types';
import { apply as applyGame, type GameAction } from './game-session';
import { apply as applyListen, type ListenAction } from './listen-session';
import { otherDevicesInCall } from './devices';
import { deviceOf, peerIdFor } from './peer-identity';
import { CallsService, type ReportedUsage } from './modules/calls/calls.service';

const HEARTBEAT_INTERVAL_MS = 30_000;

/**
 * How long a peer's seat is held after its socket closes, before the others are
 * told it has gone.
 *
 * A phone loses its signalling socket constantly - a lift, a train, a screen
 * that went off, a doze the system decided on - and it comes back within a
 * second or two. Announcing `peer.left` the instant the socket drops made every
 * one of those a full mesh teardown: everybody closed their peer connection to
 * it, it rejoined, and everybody built a new one and renegotiated from nothing.
 * That is the call that connects, drops and connects again in a loop, and none
 * of it was ever about the media path.
 *
 * Inside this window a peer that comes back with the same id is not announced
 * as leaving or as arriving. Nobody's connection is touched, and ICE - which
 * has its own restart and its own deadline in every client - is left to do the
 * one job that is actually its own: find the media a path again.
 *
 * Shorter than the heartbeat, so a seat cannot outlive the roster that would
 * have corrected it, and much shorter than any client's signalling deadline.
 */
const REJOIN_GRACE_MS = 15_000;

/**
 * The ceiling the mesh imposes, enforced where it can be said clearly rather
 * than discovered as a call that degrades for everyone at once. Each
 * participant uploads one copy of its media per other participant, so the cost
 * of the tenth joiner is paid by the nine already talking.
 *
 * ponytail: a flat number for every channel. Per-channel limits are the fix if
 * a deployment ever wants voice-only rooms to go higher than video ones.
 */
const MAX_PEERS_PER_CALL = 8;

/**
 * How many numbers a move may carry beyond its index. A carrom shot needs
 * three; nothing needs more, and an array a client chose the length of is an
 * array a client chose the length of.
 */
const MAX_MOVE_PARAMS = 4;

/**
 * The numbers that complete a move, trimmed to something the rules can be
 * handed safely.
 *
 * This is the one field a client fills in with real numbers rather than an
 * index, and it goes straight into a physics simulation - so a NaN, an infinity
 * or an array of ten thousand entries would each be a shot that never comes to
 * rest, in a loop this process is running. Anything unusable becomes
 * `undefined`, which every rules module reads as "no aim given" and refuses.
 */
function sanitiseParams(params: unknown): number[] | undefined {
  if (!Array.isArray(params)) return undefined;
  if (params.length === 0 || params.length > MAX_MOVE_PARAMS) return undefined;
  const numbers = params.filter(
    (value): value is number => typeof value === 'number' && Number.isFinite(value),
  );
  if (numbers.length !== params.length) return undefined;
  return numbers;
}

interface SocketState extends CallPeer {
  channelId: string | null;
  alive: boolean;
  /** `iat` of the token that opened this socket. See `dropRevokedSockets`. */
  issuedAt: number;
  /** The open row in this person's call log, while they are in a call. */
  sessionId: string | null;
  /** Everybody else who has been in the call since this socket joined it. */
  metUserIds: Set<string>;
  /** What the client says it moved, reported on the way out. See `leave`. */
  usage: ReportedUsage;
}

@Injectable()
export class CallGateway implements OnModuleDestroy {
  private server: WebSocketServer | null = null;
  private heartbeat: NodeJS.Timeout | null = null;
  private readonly state = new WeakMap<WebSocket, SocketState>();
  /**
   * channelId -> the sockets in that call.
   *
   * ponytail: in process, so this holds for a single call-service replica -
   * which is what the compose deployment runs. Two replicas would each see half
   * a call and peers would never be introduced across them. The upgrade path is
   * the one presence-service already uses: Redis Pub/Sub, with the roster in
   * Redis and signals published to a channel keyed by peer id.
   */
  private readonly calls = new Map<string, Set<WebSocket>>();

  /**
   * channelId -> the socket currently sharing its screen, if any.
   *
   * One share per call. Two of them is a stage with two pictures on it and no
   * way to say which one anybody means; every product that has tried it ended
   * up here. Held beside the roster rather than derived from the peer data
   * channels, because arbitration needs one answer and the mesh has no ordering
   * to produce one - the last claim wins, and "last" is only a thing the
   * gateway can decide.
   */
  private readonly sharing = new Map<string, WebSocket>();

  /**
   * channelId -> the Listen Together session in that call, if there is one.
   *
   * Beside the roster for the same reason `sharing` is: two people pressing
   * pause at the same moment need one answer, and a mesh has no ordering to
   * produce one. This gateway holds the sockets, so it is the only thing that
   * can say which press happened second.
   *
   * The music itself is nowhere near here. Each client plays the track from the
   * provider over its own connection; what crosses this gateway is a queue and
   * a position - signalling, exactly like an SDP, and for exactly the same
   * reason it works through a tunnel. Sharing a browser tab with the sound on
   * would have made it media, one upload per listener, re-encoded through a
   * codec meant for speech.
   */
  private readonly listening = new Map<string, ListenSession>();

  /**
   * channelId -> the game being played in that call, if there is one.
   *
   * Here for the third time and for the same reason as `sharing` and
   * `listening`: two people clicking the same square at the same moment need
   * one answer, and a mesh has no ordering to produce one. This gateway holds
   * the sockets, so it is the only thing that can say which click was second -
   * and it is also the referee, because a board a client could set is a board a
   * client could set to won.
   *
   * Nothing here is persisted. The game lives beside the roster and dies with
   * the call, which is what it is: three rounds of Connect Four while two
   * people waited for a build has no meaning tomorrow.
   */
  private readonly playing = new Map<string, GameSession>();

  /**
   * `channelId\u0000peerId` -> the "they have gone" nobody has been told yet.
   *
   * A closed socket takes its seat off the roster straight away - a ghost in
   * the peer list is somebody a new joiner tries to call and never reaches -
   * but the *announcement* waits out [REJOIN_GRACE_MS]. A peer that comes back
   * with the same id cancels it, and the rest of the call never learns anything
   * happened.
   */
  private readonly departing = new Map<string, NodeJS.Timeout>();

  constructor(
    private readonly logger: Logger,
    private readonly events: EventBus,
    /** Where a call's log entry is opened and closed - `this.calls` is the roster. */
    private readonly history: CallsService,
  ) {}

  /**
   * Says who is in a call, for anybody drawing it.
   *
   * The roster used to be whatever each client told presence-service it was
   * doing, which meant a client could put itself in a channel it had never
   * signalled into, and a client that crashed stayed in one until its presence
   * socket noticed. This gateway is the only thing that knows the truth - it
   * holds the sockets - so it is the thing that says it, on every change,
   * including the changes nobody announced.
   */
  private announceRoster(channelId: string): void {
    const userIds = [
      ...new Set(
        [...(this.calls.get(channelId) ?? [])].flatMap((member) => {
          const peer = this.state.get(member);
          return peer ? [peer.userId] : [];
        }),
      ),
    ];

    // One account with two windows is one person in the room, which is why this
    // is a set: the peer list is per socket and the roster is per person.
    void this.events
      .publish(EVENTS.CALL_ROSTER, { voice: { channelId, userIds } })
      .catch((error) => {
        this.logger.warn('Could not publish a call roster', {
          channelId,
          reason: String(error),
        });
      });
  }

  /**
   * Every socket this instance holds for one account.
   *
   * Scanned rather than looked up in a room: the four gateways keep different
   * bookkeeping and `clients` is the one thing all of them have. A revocation is
   * rare, and a scan of one instance's sockets is nothing.
   */
  private socketsOf(userId: string): WebSocket[] {
    return [...(this.server?.clients ?? [])].filter(
      (socket) => this.state.get(socket)?.userId === userId,
    );
  }

  attach(httpServer: HttpServer): void {
    // The socket this matters most for, and the reason the fix is a revocation
    // event and not a shorter socket lifetime: closing a call socket ends a
    // call, so it must happen when somebody says so and never on a timer.
    // `close` runs the same teardown a dropped connection does - the roster is
    // re-announced and the call log row is closed - so the other people in the
    // call see them leave rather than freeze.
    void dropRevokedSockets(
      this.events,
      (userId) => this.socketsOf(userId),
      (socket) => this.state.get(socket)?.issuedAt,
      (socket, code, reason) => socket.close(code, reason),
      (userId, count, reason) => this.logger.info('Sockets revoked', { userId, count, reason }),
    );

    this.server = new WebSocketServer({
      server: httpServer,
      path: '/ws/call',
      maxPayload: SIGNAL_MAX_PAYLOAD,
    });

    this.server.on('connection', (socket, request) => {
      const user = authenticateHandshake(request);
      if (!user) {
        socket.close(4401, 'Unauthorized');
        return;
      }

      // A peer id per device, not per socket and not per user. Two windows on
      // one account are still two peers - that is what stops the second one
      // disconnecting the first - but a reconnect from the same window is the
      // same peer, which is what stops a tunnel from rebuilding the mesh. See
      // `peerIdFor`.
      const state: SocketState = {
        peerId: peerIdFor(user.id, deviceOf(request.url)),
        userId: user.id,
        username: user.username,
        channelId: null,
        alive: true,
        issuedAt: user.issuedAt,
        sessionId: null,
        metUserIds: new Set<string>(),
        usage: noUsage(),
      };
      this.state.set(socket, state);
      this.send(socket, { type: 'ready', peerId: state.peerId });

      socket.on('pong', () => {
        const current = this.state.get(socket);
        if (current) current.alive = true;
      });

      socket.on('message', (raw) => {
        void this.handle(socket, raw.toString());
      });

      // A socket that simply closed is a network, not a decision - and on a
      // phone it is a network that comes back in a second. The seat is held.
      socket.on('close', () => this.depart(socket, { hold: true }));

      socket.on('error', (error) => {
        this.logger.warn('Call socket error', { userId: user.id, reason: String(error) });
      });
    });

    this.heartbeat = setInterval(() => {
      for (const socket of this.server?.clients ?? []) {
        const state = this.state.get(socket);
        if (!state) continue;
        if (!state.alive) {
          // Terminating fires 'close', which is what takes them off the roster
          // and tells the others to tear their peer connection down.
          socket.terminate();
          continue;
        }
        state.alive = false;
        socket.ping();
      }

      // Said again, unchanged, on every beat.
      //
      // A roster is a replacement for one channel, so a channel that stops
      // being mentioned keeps whatever was last said about it - and if this
      // process restarted mid-call, what was last said about it was true of a
      // process that no longer exists. That is the ghost in a voice channel's
      // member list: somebody who left hours ago, listed forever, because the
      // only thing that could correct it never spoke about that channel again.
      //
      // Re-announcing turns the roster into something with a heartbeat, which
      // is what presence-service ages out. Nobody in this call means nothing is
      // published for it, which is exactly what "empty" has to look like.
      for (const channelId of this.calls.keys()) this.announceRoster(channelId);
    }, HEARTBEAT_INTERVAL_MS);

    this.logger.info('Call signalling gateway ready', { path: '/ws/call' });
  }

  private async handle(socket: WebSocket, raw: string): Promise<void> {
    const state = this.state.get(socket);
    if (!state) return;

    let event: ClientCallEvent;
    try {
      event = JSON.parse(raw) as ClientCallEvent;
    } catch {
      this.send(socket, { type: 'error', code: 'BAD_PAYLOAD', message: 'Malformed JSON' });
      return;
    }

    switch (event.type) {
      case 'join':
        await this.join(socket, state, event.channelId);
        return;

      case 'leave':
        // The only number in the log the server cannot take for itself: media
        // is peer to peer, so the client's own counters are the only counters.
        // It is clamped where it is written - see `usage.ts`.
        state.usage = {
          bytes: typeof event.bytes === 'number' ? event.bytes : 0,
          bytesSent: typeof event.bytesSent === 'number' ? event.bytesSent : 0,
          bytesReceived: typeof event.bytesReceived === 'number' ? event.bytesReceived : 0,
          links: event.links,
        };
        // Somebody pressed the button. No grace: they are not coming back, and
        // holding their seat is fifteen seconds of a frozen tile for everybody.
        this.depart(socket);
        return;

      case 'signal':
        this.relay(state, event.to, event.data);
        return;

      case 'screen.claim':
        this.claimScreen(socket, state);
        return;

      case 'screen.release':
        this.releaseScreen(socket, state);
        return;

      case 'ping':
        // The gateway's clock rides along, because a shared position is
        // meaningless without one: two machines disagree about what time it is
        // by whatever their clocks last drifted to, and this is the reference
        // every client measures its own offset against.
        this.send(socket, { type: 'pong', serverMs: Date.now() });
        return;

      case 'listen.add':
        this.listen(state, {
          kind: 'add',
          playNow: event.playNow === true,
          track: {
            // Minted here, not by the client: it is the identity two clients
            // agree a queue entry has, and a client that chose its own could
            // collide with one already in the queue - which is a `remove` that
            // takes away somebody else's track.
            id: randomUUID(),
            provider: event.provider,
            ref: event.ref,
            title: typeof event.title === 'string' ? event.title : '',
            durationMs: 0,
            addedByUserId: state.userId,
            addedByUsername: state.username,
          },
        });
        return;

      case 'listen.remove':
        this.listen(state, { kind: 'remove', trackId: event.trackId });
        return;

      case 'listen.play':
        this.listen(state, { kind: 'play', index: event.index });
        return;

      case 'listen.pause':
        this.listen(state, { kind: 'pause', positionMs: event.positionMs });
        return;

      case 'listen.seek':
        this.listen(state, { kind: 'seek', positionMs: event.positionMs });
        return;

      case 'listen.skip':
        this.listen(state, { kind: 'skip', delta: event.delta });
        return;

      case 'listen.stop':
        this.listen(state, { kind: 'stop' });
        return;

      case 'listen.ended':
        this.listen(state, { kind: 'ended', trackId: event.trackId });
        return;

      case 'listen.meta':
        this.listen(state, {
          kind: 'meta',
          trackId: event.trackId,
          title: event.title,
          durationMs: event.durationMs,
        });
        return;

      case 'game.open':
        this.game(state, { kind: 'open', gameId: event.gameId });
        return;

      case 'game.sit':
        this.game(state, { kind: 'sit', seat: event.seat });
        return;

      case 'game.move':
        this.game(state, {
          kind: 'move',
          move: event.move,
          // Bounded and cleaned here rather than trusted: this is the one field
          // a client fills in with real numbers, and it goes straight into a
          // physics simulation. A NaN, an array of ten thousand, or an infinity
          // would each be a shot that never comes to rest.
          params: sanitiseParams(event.params),
        });
        return;

      case 'game.rematch':
        this.game(state, { kind: 'rematch' });
        return;

      case 'game.close':
        this.game(state, { kind: 'close' });
        return;

      default:
        this.send(socket, { type: 'error', code: 'UNKNOWN_EVENT', message: 'Unsupported event' });
    }
  }

  private holdKey(channelId: string, peerId: string): string {
    return `${channelId}\u0000${peerId}`;
  }

  /**
   * Whether this join is the same peer coming back inside its grace window.
   *
   * True means the others still hold a live peer connection to it and must not
   * be told about any of this: no `peer.left` (cancelled here) and no
   * `peer.joined` (suppressed by the caller).
   */
  private resumeHeldSeat(channelId: string, peerId: string): boolean {
    const key = this.holdKey(channelId, peerId);
    const timer = this.departing.get(key);
    if (!timer) return false;
    clearTimeout(timer);
    this.departing.delete(key);
    return true;
  }

  private async join(socket: WebSocket, state: SocketState, channelId: string): Promise<void> {
    const access = await resolveChannelAccess(state.userId, channelId);
    if (!access) {
      // 404-shaped, for the same reason the REST path is: a non-member must not
      // learn the channel exists.
      this.send(socket, { type: 'error', code: 'CHANNEL_NOT_FOUND', message: 'Channel not found' });
      return;
    }
    if (!access.permissions.includes(PERMISSIONS.START_CALL)) {
      this.send(socket, {
        type: 'error',
        code: 'MISSING_PERMISSION',
        message: `Missing permission ${PERMISSIONS.START_CALL}`,
      });
      return;
    }

    // One call per socket. Leaving the old one first keeps a roster honest when
    // a client switches channels without saying goodbye to the first.
    if (state.channelId && state.channelId !== channelId) this.depart(socket, { keepOpen: true });

    // One call per *account*, across every device it is signed in on. A peer id
    // is still per socket - two windows are still two ends of two connections -
    // but only one of them may be in a call at a time, so joining on the laptop
    // takes the call off the desktop rather than putting the same person in the
    // room twice, talking over themselves through two microphones.
    //
    // The old device is told why before it is dropped: `superseded` is what
    // lets it say "this call moved" instead of "the connection was lost". Its
    // socket stays open, so it can join again - which is what moving the call
    // back looks like from the other end.
    const otherDevices = otherDevicesInCall(
      this.calls.values(),
      (member) => this.state.get(member)?.userId,
      state.userId,
      socket,
    );
    for (const other of otherDevices) {
      // The same peer id is this device reconnecting, not another one: an old
      // socket the far end has not finished closing while its replacement is
      // already joining. It is not superseded, it is replaced - so it goes
      // quietly, holding its seat for the join happening two lines below. Told
      // otherwise, a phone with a slow-closing socket would announce its own
      // departure and arrival on every reconnect, which is the rebuild this
      // whole change exists to stop.
      const replaced = this.state.get(other)?.peerId === state.peerId;
      if (replaced) {
        this.depart(other, { keepOpen: true, hold: true });
        continue;
      }
      this.send(other, { type: 'superseded', channelId });
      this.depart(other, { keepOpen: true });
      this.logger.info('Call moved to another device', { userId: state.userId, channelId });
    }

    const members = this.calls.get(channelId) ?? new Set<WebSocket>();
    if (!members.has(socket) && members.size >= MAX_PEERS_PER_CALL) {
      this.send(socket, {
        type: 'error',
        code: 'CALL_FULL',
        message:
          `This call already has ${MAX_PEERS_PER_CALL} people in it. Media goes directly between ` +
          'participants, so every extra person costs everyone already talking another upload.',
      });
      return;
    }

    // The roster is taken before this socket is added, so a joiner is not told
    // about itself and does not try to connect to its own peer id.
    const peers: CallPeer[] = [...members].flatMap((member) => {
      const peer = this.state.get(member);
      return peer ? [{ peerId: peer.peerId, userId: peer.userId, username: peer.username }] : [];
    });

    // Who they are in the call with, recorded both ways: this join meets
    // everybody already here, and everybody already here has now met them. A
    // log entry is "who was in it while I was", so somebody who leaves before
    // the end still belongs in it.
    for (const member of members) {
      const peer = this.state.get(member);
      if (!peer || peer.userId === state.userId) continue;
      state.metUserIds.add(peer.userId);
      peer.metUserIds.add(state.userId);
    }

    // Before the seat is taken back, because taking it back is what decides
    // whether anybody else is told about it.
    const resumed = this.resumeHeldSeat(channelId, state.peerId);

    members.add(socket);
    this.calls.set(channelId, members);
    state.channelId = channelId;

    this.send(socket, { type: 'joined', channelId, peers });
    // A peer coming back inside its grace window never left as far as anybody
    // else is concerned. Announcing it would be an arrival for a connection
    // every one of them already holds - and the tear-down and rebuild that
    // follows is the whole of a call that connects and drops in a loop.
    if (!resumed) {
      this.broadcast(
        channelId,
        {
          type: 'peer.joined',
          peer: { peerId: state.peerId, userId: state.userId, username: state.username },
        },
        socket,
      );
    }

    this.announceRoster(channelId);

    // Whatever is already playing, to the newcomer only. They get the position
    // and the instant it was true, so their player opens partway through the
    // track everybody else is partway through rather than at the beginning.
    const listening = this.listening.get(channelId);
    if (listening) this.send(socket, { type: 'listen.state', session: listening });

    // And whatever is on the table, to the newcomer only. They arrive at the
    // board as it stands rather than at an empty one, which is the difference
    // between joining a game and being told there is one.
    const playing = this.playing.get(channelId);
    if (playing) this.send(socket, { type: 'game.state', session: playing });

    // The log row is opened here because here is where the join is known to
    // have been allowed. If they left while this was being written - a socket
    // that closes mid-await - it is closed straight away rather than left open
    // forever, which is what an unattended `endedAt` of null means.
    state.sessionId = await this.history.startSession(state.userId, channelId);
    if (state.sessionId && state.channelId !== channelId) {
      void this.history.endSession(state.sessionId, [...state.metUserIds], state.usage);
      state.sessionId = null;
    }

    this.logger.info('Peer joined a call', {
      userId: state.userId,
      channelId,
      peers: members.size,
    });
  }

  /**
   * Hands the screen to whoever asked for it last.
   *
   * The previous holder is told the same thing everybody else is - who holds it
   * now - and stops on its own. It is not sent a private "stop": every client
   * needs the new holder anyway, and one message that says the whole truth
   * cannot be applied by half the room and missed by the rest.
   */
  private claimScreen(socket: WebSocket, state: SocketState): void {
    const channelId = state.channelId;
    if (!channelId) return;
    if (this.sharing.get(channelId) === socket) return;

    this.sharing.set(channelId, socket);
    this.announceScreen(channelId);
    this.logger.info('Screen share taken over', { userId: state.userId, channelId });
  }

  /** Gives it up, if this socket is the one holding it. */
  private releaseScreen(socket: WebSocket, state: SocketState): void {
    const channelId = state.channelId;
    if (!channelId) return;
    // Only the holder may release: a late "I stopped" from whoever was replaced
    // would otherwise take the screen away from the person who just took it.
    if (this.sharing.get(channelId) !== socket) return;

    this.sharing.delete(channelId);
    this.announceScreen(channelId);
  }

  /**
   * Runs one Listen Together action and tells the call what came of it.
   *
   * Membership is the only permission asked for, and deliberately: everybody in
   * the call can change what is playing. A host is a person who eventually
   * leaves and takes the music with them, and the point of listening together
   * is that two people are doing it, not that one is performing it.
   *
   * The whole session is broadcast rather than a delta. It is a few hundred
   * bytes, it changes when somebody presses a button rather than continuously,
   * and a client that missed one message would otherwise hold a queue nobody
   * else has - which is the failure that cannot be noticed from inside.
   */
  private listen(state: SocketState, action: ListenAction): void {
    const channelId = state.channelId;
    if (!channelId) return;

    const before = this.listening.get(channelId) ?? null;
    const after = applyListen(before, action, state.userId, Date.now());
    // Nothing happened: a `duration` for a track that already had one, or an
    // `ended` for a track that stopped being current before it arrived. Saying
    // so anyway would make every client re-seek for no reason.
    if (after === before) return;

    if (after) this.listening.set(channelId, after);
    else this.listening.delete(channelId);

    this.broadcast(channelId, { type: 'listen.state', session: after });
  }

  /**
   * Runs one Play Together action and tells the call what came of it.
   *
   * The gateway is the referee, and this is the only place a board is ever
   * made: a client sends "column four", never a board. The rules come from
   * `@betweenus/shared-types`, which is also where the clients read them, so
   * what everybody draws and what is agreed here cannot drift apart.
   *
   * Membership is the only permission asked for. Who may *move* is a question
   * about the seats rather than about the channel, and the reducer answers it.
   */
  private game(state: SocketState, action: GameAction): void {
    if (!state.channelId) return;
    this.runGame(state.channelId, { userId: state.userId, username: state.username }, action);
  }

  /**
   * The same thing, addressed by channel rather than by socket.
   *
   * `depart` needs this: it clears `state.channelId` before it does anything
   * else, so by the time a leaver's chair has to be freed the socket no longer
   * knows which call it was in.
   */
  private runGame(
    channelId: string,
    actor: { userId: string; username: string },
    action: GameAction,
  ): void {
    const before = this.playing.get(channelId) ?? null;
    const after = applyGame(before, action, actor);
    // Nothing happened: an illegal move, a chair that filled while the click
    // was in flight, a rematch from somebody watching. Broadcasting anyway
    // would make every client redraw a board it already has.
    if (after === before) return;

    if (after) this.playing.set(channelId, after);
    else this.playing.delete(channelId);

    this.broadcast(channelId, { type: 'game.state', session: after });
  }

  private announceScreen(channelId: string): void {
    const holder = this.sharing.get(channelId);
    const peer = holder ? this.state.get(holder) : undefined;
    this.broadcast(channelId, {
      type: 'screen.holder',
      peerId: peer?.peerId ?? null,
      userId: peer?.userId ?? null,
    });
  }

  /**
   * Forwards one signal to one peer in the same call.
   *
   * Same-call is the check that matters: without it, a peer id learned anywhere
   * would let a client offer a connection into a channel it cannot see.
   */
  private relay(from: SocketState, to: string, data: unknown): void {
    if (!from.channelId) return;

    for (const member of this.calls.get(from.channelId) ?? []) {
      const peer = this.state.get(member);
      if (peer?.peerId !== to) continue;
      this.send(member, {
        type: 'signal',
        from: from.peerId,
        data: data as never,
      });
      return;
    }
  }

  /**
   * Takes a socket off its call and tells the others.
   *
   * `keepOpen` is the channel-switch case: the socket lives on, so its state is
   * kept and only its membership is dropped.
   */
  private depart(socket: WebSocket, options: DepartOptions = {}): void {
    const { keepOpen = false, hold = false } = options;
    const state = this.state.get(socket);
    if (!state) return;

    const { channelId, sessionId } = state;
    state.channelId = null;

    // Closed before anything else can throw, and before the state is dropped:
    // this is the only moment the duration is knowable, and a row left open is
    // an entry that reads as a call that never ended.
    if (sessionId) {
      state.sessionId = null;
      void this.history.endSession(sessionId, [...state.metUserIds], state.usage);
    }
    // A socket that stays open to join elsewhere starts a fresh log entry, so
    // it starts with a fresh idea of who it has met and what it has moved.
    state.metUserIds = new Set<string>();
    state.usage = noUsage();

    if (!keepOpen) this.state.delete(socket);
    if (!channelId) return;

    const members = this.calls.get(channelId);
    if (!members) return;
    members.delete(socket);
    if (members.size === 0) {
      this.calls.delete(channelId);
      // Nobody is listening, so there is nothing to listen to. The queue was a
      // thing this call built and it goes when the call does - keeping it would
      // mean the next person to join a quiet channel is played whatever the
      // last people left half-finished.
      this.listening.delete(channelId);
      // Same for the board: nobody is at the table, so there is no game. A kept
      // one would be a half-finished Reversi position waiting for whoever walks
      // into a quiet channel next.
      this.playing.delete(channelId);
    }

    // Somebody who left is not still sharing. Without this the screen stays
    // claimed by a socket that has gone, and the next person to press the
    // button is the only one who ever finds out.
    if (this.sharing.get(channelId) === socket) {
      this.sharing.delete(channelId);
      this.announceScreen(channelId);
    }

    // Everyone still in the call has a peer connection to this peer that will
    // never produce another frame. Saying so is what closes it; waiting for ICE
    // to time out is thirty seconds of a frozen tile.
    //
    // Unless nobody has said they are leaving. A socket that simply closed is a
    // network, not a decision, and on a phone it is a network that comes back
    // in a second - so the seat is held and the announcement waits. See
    // REJOIN_GRACE_MS.
    //
    // The chair at the game table is held on exactly the same terms, and it
    // has to be: freeing it the instant a socket blinks would let somebody else
    // sit down mid-game while the player it belongs to is still reconnecting.
    const actor = { userId: state.userId, username: state.username };
    if (!hold) {
      this.announceDeparture(channelId, state.peerId);
      this.runGame(channelId, actor, { kind: 'vacate', userId: state.userId });
    } else {
      const key = this.holdKey(channelId, state.peerId);
      const held = state.peerId;
      clearTimeout(this.departing.get(key));
      this.departing.set(
        key,
        setTimeout(() => {
          this.departing.delete(key);
          this.announceDeparture(channelId, held);
          this.runGame(channelId, actor, { kind: 'vacate', userId: actor.userId });
        }, REJOIN_GRACE_MS),
      );
    }

    this.logger.info('Peer left a call', {
      userId: state.userId,
      channelId,
      peers: members.size,
      held: hold,
    });
  }

  /** They are not coming back: tell the call, and correct the roster. */
  private announceDeparture(channelId: string, peerId: string): void {
    this.broadcast(channelId, { type: 'peer.left', peerId });
    this.announceRoster(channelId);
  }

  private broadcast(channelId: string, event: ServerCallEvent, except?: WebSocket): void {
    for (const member of this.calls.get(channelId) ?? []) {
      if (member === except) continue;
      this.send(member, event);
    }
  }

  private send(socket: WebSocket, event: ServerCallEvent): void {
    if (socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify(event));
  }

  onModuleDestroy(): void {
    if (this.heartbeat) clearInterval(this.heartbeat);
    for (const timer of this.departing.values()) clearTimeout(timer);
    this.departing.clear();
    this.server?.close();
  }
}

/**
 * How a socket is being taken off a call.
 *
 * `keepOpen` says the socket lives on - a channel switch, or a device being
 * replaced - so its state is kept and only its membership dropped. `hold` says
 * nobody has announced anything: the seat is kept for [REJOIN_GRACE_MS] and the
 * rest of the call is told only if it is not claimed back.
 */
interface DepartOptions {
  keepOpen?: boolean;
  hold?: boolean;
}

/** A stay nobody reported on: a window closed mid-call, or an older client. */
function noUsage(): ReportedUsage {
  return { bytes: 0, bytesSent: 0, bytesReceived: 0, links: [] };
}

import { Body, Controller, Get, HttpCode, Post, Query, UseGuards } from '@nestjs/common';
import { CurrentUser, JwtAuthGuard, type AuthenticatedUser } from '@betweenus/auth';
import type { CallAnalytics, CallHistoryEntry, CallIceResponse } from '@betweenus/shared-types';
import { CallsService } from './calls.service';
import { CallDeclineDto, CallIceDto, CallRingDto } from './dto';

@Controller('calls')
@UseGuards(JwtAuthGuard)
export class CallsController {
  constructor(private readonly calls: CallsService) {}

  /**
   * No `Host` header is read here, unlike the token endpoint this replaced.
   * That header existed to catch a media-server address the caller could never
   * reach; nothing is advertised to a caller any more, so there is nothing that
   * could be wrong about where they are.
   */
  @Post('ice')
  ice(@CurrentUser() user: AuthenticatedUser, @Body() dto: CallIceDto): Promise<CallIceResponse> {
    return this.calls.ice(user.id, dto.channelId);
  }

  /**
   * "Come into this call."
   *
   * The caller is the authenticated user and never the body: a ring that could
   * name its own sender is a ring that could be sent as somebody else.
   */
  /**
   * This account's own call log. Whose is never a parameter: the only thing
   * that could be wrong about a private history is reading somebody else's.
   */
  @Get('history')
  history(@CurrentUser() user: AuthenticatedUser): Promise<CallHistoryEntry[]> {
    return this.calls.history(user.id);
  }

  /**
   * The same rows added up, for the page the log hangs under.
   *
   * `days` is a hint and not a promise: the service clamps it, because a client
   * asking for a hundred thousand days is a client asking for every row it has
   * ever written.
   */
  @Get('analytics')
  analytics(
    @CurrentUser() user: AuthenticatedUser,
    @Query('days') days?: string,
  ): Promise<CallAnalytics> {
    return this.calls.analytics(user.id, Number(days));
  }

  @Post('ring')
  @HttpCode(204)
  ring(@CurrentUser() user: AuthenticatedUser, @Body() dto: CallRingDto): Promise<void> {
    return this.calls.ring(user.id, dto.channelId, dto.userId);
  }

  /**
   * "I said no to that." Reaches this account's other devices and nobody else -
   * see `CallsService.decline`.
   */
  @Post('decline')
  @HttpCode(204)
  decline(@CurrentUser() user: AuthenticatedUser, @Body() dto: CallDeclineDto): Promise<void> {
    return this.calls.decline(user.id, dto.channelId);
  }
}

/**
 * `/ws/presence` realtime gateway: online status, typing indicators and voice
 * channel membership.
 *
 * State lives in Redis and changes fan out over Redis Pub/Sub, so several
 * presence-service instances stay consistent without sticky sessions - the same
 * pattern the chat gateway uses.
 */
import { Injectable, OnModuleDestroy } from '@nestjs/common';
import type { Server as HttpServer } from 'node:http';
import { WebSocket, WebSocketServer } from 'ws';
import { EVENTS, EventBus } from '@betweenus/events';
import { resolveChannelAccess } from '@betweenus/database';
import { PERMISSIONS } from '@betweenus/permissions';
import { Logger } from '@betweenus/logger';
import {
  CONTROL_MAX_PAYLOAD,
  authenticateHandshake,
  dropRevokedSockets,
} from '@betweenus/websocket';
import type { ClientPresenceEvent, ServerPresenceEvent } from '@betweenus/shared-types';
import { PresenceStore, isActiveStatus } from './presence.store';
import { audienceOfChannel, audienceOfUser } from './audience';

const HEARTBEAT_INTERVAL_MS = 30_000;

/**
 * The most accounts one `presence.query` will answer for.
 *
 * A card opens for one person and a conversation header asks about one; the
 * largest honest batch is a member column, and a column longer than this is
 * scrolled rather than read at once. The cap is here so that a client asking
 * about the whole user table gets an answer about a hundred of them instead of
 * a database query per id.
 */
const QUERY_LIMIT = 100;

interface SocketState {
  userId: string;
  username: string;
  alive: boolean;
  /** `iat` of the token that opened this socket. See `dropRevokedSockets`. */
  issuedAt: number;
  /**
   * The channel this window has on screen, or null. One at a time: a window
   * shows one conversation, and a second focus replaces the first rather than
   * adding to it.
   */
  focused: string | null;
}

@Injectable()
export class PresenceGateway implements OnModuleDestroy {
  private server: WebSocketServer | null = null;
  private heartbeat: NodeJS.Timeout | null = null;
  private readonly state = new WeakMap<WebSocket, SocketState>();

  constructor(
    private readonly store: PresenceStore,
    private readonly events: EventBus,
    private readonly logger: Logger,
  ) {}

  async attach(httpServer: HttpServer): Promise<void> {
    this.server = new WebSocketServer({
      server: httpServer,
      path: '/ws/presence',
      maxPayload: CONTROL_MAX_PAYLOAD,
    });

    this.server.on('connection', (socket, request) => {
      const user = authenticateHandshake(request);
      if (!user) {
        socket.close(4401, 'Unauthorized');
        return;
      }

      this.state.set(socket, {
        userId: user.id,
        username: user.username,
        alive: true,
        issuedAt: user.issuedAt,
        focused: null,
      });
      void this.onConnect(socket, user.id);

      socket.on('pong', () => {
        const state = this.state.get(socket);
        if (state) state.alive = true;
      });

      socket.on('message', (raw) => {
        void this.handleClientEvent(socket, raw.toString());
      });

      socket.on('close', () => {
        void this.onDisconnect(socket, user.id);
      });

      socket.on('error', (error) => {
        this.logger.warn('Presence socket error', { userId: user.id, reason: String(error) });
      });
    });

    this.heartbeat = setInterval(() => {
      for (const socket of this.server?.clients ?? []) {
        const state = this.state.get(socket);
        if (!state) continue;
        if (!state.alive) {
          socket.terminate();
          continue;
        }
        state.alive = false;
        socket.ping();
        // A live socket is a live user; this is what keeps them out of the
        // stale window in Redis.
        void this.store.touch(state.userId);
        // And a live socket still looking at a channel is still looking at it.
        // Without this the focus ages out after 90 seconds and a phone starts
        // buzzing for a conversation that is open on a desktop.
        if (state.focused) void this.store.focus(state.focused, state.userId);
      }

      void this.sweepVoice();
    }, HEARTBEAT_INTERVAL_MS);

    // Every one of these is scoped. A status change reaches the people who
    // share a server or a friendship with whoever changed; anything about a
    // channel reaches the people who can see that channel. Nothing goes to
    // every connected socket any more.
    // An account whose authority was withdrawn loses the sockets it already
    // had, which is the half of a revocation that was missing: a handshake is
    // checked once and then trusted until it happens to disconnect.
    await dropRevokedSockets(
      this.events,
      (userId) => this.socketsOf(userId),
      (socket) => this.state.get(socket)?.issuedAt,
      (socket, code, reason) => socket.close(code, reason),
      (userId, count, reason) => this.logger.info('Sockets revoked', { userId, count, reason }),
    );

    await this.events.subscribe(EVENTS.PRESENCE_CHANGED, (envelope) => {
      const { user } = envelope.payload;
      void this.broadcastTo(audienceOfUser(user.userId), { type: 'presence.changed', user });
    });
    await this.events.subscribe(EVENTS.PRESENCE_TYPING, (envelope) => {
      const { channelId, userId, username } = envelope.payload;
      void this.broadcastTo(
        audienceOfChannel(channelId),
        { type: 'typing', channelId, userId, username },
        userId,
      );
    });
    await this.events.subscribe(EVENTS.PRESENCE_VOICE, (envelope) => {
      const { voice } = envelope.payload;
      void this.broadcastTo(audienceOfChannel(voice.channelId), { type: 'voice.changed', voice });
    });

    // The roster as call-service holds it, which is the only place it is really
    // known: it owns the signalling sockets, so it sees a join, a departure and
    // a crash alike. Written through to Redis so a client connecting later gets
    // the same answer in its sync.
    await this.events.subscribe(EVENTS.CALL_ROSTER, (envelope) => {
      const { voice } = envelope.payload;
      void this.store
        .replaceVoice(voice.channelId, voice.userIds)
        .then(() =>
          this.broadcastTo(audienceOfChannel(voice.channelId), { type: 'voice.changed', voice }),
        )
        .catch((error) => {
          this.logger.warn('Could not apply a call roster', {
            channelId: voice.channelId,
            reason: String(error),
          });
        });
    });

    // Somebody is ringing somebody else into a call. Straight to the person
    // being rung and to nobody else - a ring is directed, so it has no
    // audience to scope to and there is nothing here to broadcast.
    //
    // Every instance receives this and delivers to its own sockets; an
    // instance the target is not connected to does nothing, which is what
    // `sendToUser` already means. The push fan-out covers the devices that are
    // not connected to any of them.
    await this.events.subscribe(EVENTS.CALL_RING, (envelope) => {
      const ring = envelope.payload;
      this.sendToUser(ring.targetId, {
        type: 'call.ring',
        channelId: ring.channelId,
        channelName: ring.channelName,
        callerId: ring.callerId,
        callerName: ring.callerName,
        ...(ring.callerAvatarUrl ? { callerAvatarUrl: ring.callerAvatarUrl } : {}),
      });
    });

    // Somebody said no to a ring, on one of their devices. Straight back to
    // that same account and to nobody else - the caller is deliberately not
    // told, and nobody else was ever ringing.
    //
    // Answering needs no equivalent: a running client sees itself arrive in
    // `call.roster` above and draws the same conclusion. Declining reaches no
    // roster, so without this a laptop went on ringing after somebody said no
    // on their phone.
    await this.events.subscribe(EVENTS.CALL_DECLINED, (envelope) => {
      const { userId, channelId } = envelope.payload;
      this.sendToUser(userId, { type: 'call.handled', channelId, how: 'declined' });
    });

    this.logger.info('Presence WebSocket gateway ready', { path: '/ws/presence' });
  }

  /**
   * Empties the voice channels `call-service` has stopped speaking for.
   *
   * Its rosters expire now (see `replaceVoice`), which is what makes a call
   * that outlived its own service stop being a room full of ghosts. Expiring in
   * Redis fixes the next client to connect; this is what fixes the ones already
   * looking at it, which is where the ghost was actually being seen.
   */
  private async sweepVoice(): Promise<void> {
    try {
      for (const channelId of await this.store.expireVoice()) {
        await this.broadcastTo(audienceOfChannel(channelId), {
          type: 'voice.changed',
          voice: { channelId, userIds: [] },
        });
      }
    } catch (error) {
      this.logger.warn('Could not expire the call rosters', { reason: String(error) });
    }
  }

  private async onConnect(socket: WebSocket, userId: string): Promise<void> {
    await this.store.touch(userId);

    // Nothing is cleared here any more. A client connecting used to drop itself
    // from every voice channel on the assumption that a leftover was a dead
    // session - which was a fair guess while the roster was client-written, and
    // is now wrong: the roster belongs to call-service, and this connection
    // says nothing about whether that one is still up.
    this.send(socket, { type: 'ready', userId });

    const [users, voice, own, audience] = await Promise.all([
      this.store.onlineUsers(),
      this.store.allVoiceStates(),
      // The chosen status survives a restart, so the picker has to be told what
      // it currently is rather than assuming "online".
      this.store.statusOf(userId),
      audienceOfUser(userId),
    ]);

    // The same scoping the live events get. Without it the first message on a
    // socket is the whole deployment's online list, and every later one is
    // filtered - which is the sort of half-done that looks like it works.
    const visibleUsers = users.filter((user) => audience.has(user.userId));
    const rooms = await Promise.all(
      voice.map(async (room) => ({
        room,
        allowed: (await audienceOfChannel(room.channelId)).has(userId),
      })),
    );
    const visibleVoice = rooms.filter((entry) => entry.allowed).map((entry) => entry.room);

    this.send(socket, { type: 'presence.sync', users: visibleUsers, voice: visibleVoice });
    this.send(socket, { type: 'status.self', status: own });

    await this.publishStatus(userId);
    this.logger.info('Presence connected', { userId });
  }

  /** Tells everyone else what this user looks like, invisible resolved away. */
  private async publishStatus(userId: string): Promise<void> {
    const status = await this.store.visibleStatusOf(userId);
    await this.events.publish(EVENTS.PRESENCE_CHANGED, { user: { userId, status } });
  }

  private async onDisconnect(socket: WebSocket, userId: string): Promise<void> {
    const state = this.state.get(socket);
    this.state.delete(socket);

    // Before the early return below: this window is gone whether or not the
    // user has others, and a window that is gone is not reading anything.
    //
    // Focus is per user, so the entry is only removed if no *other* window of
    // theirs is still on that channel. Removing it unconditionally would leave
    // a gap - up to one heartbeat - in which a phone is woken for a
    // conversation that is open on a second screen right now.
    if (state?.focused && !this.stillFocused(userId, state.focused, socket)) {
      await this.store.blur(state.focused, userId);
    }

    // Another window of the same user may still be connected to this instance.
    if (this.hasOtherSocket(userId, socket)) return;

    await this.store.goOffline(userId);

    // The last window of this account has gone, so the last-seen value has
    // stopped moving - which is the moment it is worth a row rather than a
    // Redis key.
    await this.store.flushLastSeen(userId);

    // The event deliberately carries no timestamp. Who may read one depends on
    // the reader - the subject's `LastSeenVisibility`, a friendship, and whether
    // the reader has hidden their own - and a broadcast has one payload for
    // every recipient. Clients that care ask with `presence.query` when they see
    // somebody go offline, and that road is per-asker and can answer honestly.
    //
    // The call roster is not touched: a presence socket closing is not evidence
    // that a call ended, and call-service publishes the departure itself the
    // moment its own socket goes - including when it goes by being terminated
    // for missing a heartbeat.
    await this.events.publish(EVENTS.PRESENCE_CHANGED, {
      user: { userId, status: 'offline' },
    });
    this.logger.info('Presence disconnected', { userId });
  }

  /** Has this user another live window on `channelId`? See `onDisconnect`. */
  private stillFocused(userId: string, channelId: string, except: WebSocket): boolean {
    for (const socket of this.server?.clients ?? []) {
      if (socket === except) continue;
      if (socket.readyState !== WebSocket.OPEN) continue;
      const state = this.state.get(socket);
      if (state?.userId === userId && state.focused === channelId) return true;
    }
    return false;
  }

  /**
   * Every socket this instance holds for one account.
   *
   * Scanned rather than looked up in a room: the four gateways keep different
   * bookkeeping and `clients` is the one thing all of them have. A revocation is
   * rare, and a scan of one instance's sockets is nothing.
   */
  private socketsOf(userId: string): WebSocket[] {
    return [...(this.server?.clients ?? [])].filter(
      (socket) => this.state.get(socket)?.userId === userId,
    );
  }

  /** Is this user connected through some socket other than `except`? */
  private hasOtherSocket(userId: string, except?: WebSocket): boolean {
    for (const socket of this.server?.clients ?? []) {
      if (socket === except) continue;
      if (socket.readyState !== WebSocket.OPEN) continue;
      if (this.state.get(socket)?.userId === userId) return true;
    }
    return false;
  }

  private async handleClientEvent(socket: WebSocket, raw: string): Promise<void> {
    const state = this.state.get(socket);
    if (!state) return;

    let event: ClientPresenceEvent;
    try {
      event = JSON.parse(raw) as ClientPresenceEvent;
    } catch {
      this.send(socket, { type: 'error', code: 'BAD_PAYLOAD', message: 'Malformed JSON' });
      return;
    }

    switch (event.type) {
      case 'status.set': {
        if (!isActiveStatus(event.status)) {
          this.send(socket, {
            type: 'error',
            code: 'UNKNOWN_STATUS',
            message: 'Unsupported status',
          });
          return;
        }
        await this.store.setStatus(state.userId, event.status);
        // Every window of this user gets the real value; everyone else gets
        // what `publishStatus` resolves it to.
        this.sendToUser(state.userId, { type: 'status.self', status: event.status });
        await this.publishStatus(state.userId);
        return;
      }

      case 'ping':
        await this.store.touch(state.userId);
        this.send(socket, { type: 'pong' });
        return;

      /**
       * "When were these people last here?"
       *
       * Answered one `presence.changed` at a time rather than in a batch of its
       * own, so a client has exactly one road into its presence state and the
       * answer to a question and the news of a change are the same shape.
       *
       * Scoped through `audienceOfUser`, the same set every broadcast is scoped
       * to. Without it this would be the one event a client could aim at an
       * arbitrary id, and a "who is online" oracle over the whole deployment is
       * the thing `audience.ts` was written to remove.
       */
      case 'presence.query': {
        if (!Array.isArray(event.userIds) || event.userIds.length === 0) return;
        const asked = [...new Set(event.userIds)].slice(0, QUERY_LIMIT);

        let allowed: Set<string>;
        try {
          allowed = await audienceOfUser(state.userId);
        } catch (error) {
          this.logger.warn('Could not scope a presence query', { reason: String(error) });
          return;
        }

        const visible = asked.filter((userId) => allowed.has(userId));
        if (visible.length === 0) return;

        const [seen, statuses] = await Promise.all([
          // The privacy filter is inside this call, so anybody the asker may
          // not read is simply missing from the map - see `lastSeenOf`.
          this.store.lastSeenOf(state.userId, visible),
          Promise.all(visible.map((userId) => this.store.stateOf(userId))),
        ]);

        visible.forEach((userId, index) => {
          const status = statuses[index] ?? 'offline';
          const lastSeenAt = seen.get(userId);
          // Only for somebody who is not here. "Online, last seen a moment
          // ago" says one thing twice, and the second half goes stale first.
          this.send(socket, {
            type: 'presence.changed',
            user: {
              userId,
              status,
              ...(status === 'offline' && lastSeenAt ? { lastSeenAt } : {}),
            },
          });
        });
        return;
      }

      /**
       * The window is showing this channel and has the user's attention.
       *
       * Permission is checked, like typing: focus suppresses notifications, so
       * an unchecked one would let anybody silence a channel they cannot even
       * see for everybody who can.
       */
      case 'channel.focus': {
        if (!(await this.canAccessChannel(state.userId, event.channelId))) return;
        // One channel per window. Leaving the old one behind would have a
        // window that has moved on still suppressing the conversation it left.
        if (state.focused && state.focused !== event.channelId) {
          await this.store.blur(state.focused, state.userId);
        }
        state.focused = event.channelId;
        await this.store.focus(event.channelId, state.userId);
        return;
      }

      case 'channel.blur': {
        if (state.focused === event.channelId) state.focused = null;
        await this.store.blur(event.channelId, state.userId);
        return;
      }

      case 'typing.start':
        if (!(await this.canAccessChannel(state.userId, event.channelId))) return;
        await this.events.publish(EVENTS.PRESENCE_TYPING, {
          channelId: event.channelId,
          userId: state.userId,
          username: state.username,
        });
        return;

      // Both of these used to write the roster, which meant the roster was
      // whatever a client claimed: anybody could appear in a channel they had
      // never signalled into, and anybody who crashed stayed in one. The roster
      // now comes from `call-service`, which holds the signalling sockets and
      // therefore knows. These are kept because the permission answer is still
      // worth giving - a client that may not join should hear so from the
      // service it asked, not by watching a roster it never appears in.
      case 'voice.join': {
        if (!(await this.canAccessChannel(state.userId, event.channelId))) {
          this.send(socket, {
            type: 'error',
            code: 'CHANNEL_FORBIDDEN',
            message: 'Cannot join this voice channel',
          });
        }
        return;
      }

      case 'voice.leave':
        return;

      default:
        this.send(socket, { type: 'error', code: 'UNKNOWN_EVENT', message: 'Unsupported event' });
    }
  }

  /**
   * The same resolver chat- and call-service use. Typing and voice both need
   * only to see the channel, so `VIEW_CHANNEL` is the bar.
   */
  private async canAccessChannel(userId: string, channelId: string): Promise<boolean> {
    const access = await resolveChannelAccess(userId, channelId);
    return access !== null && access.permissions.includes(PERMISSIONS.VIEW_CHANNEL);
  }

  /** Every socket belonging to one user - a person may have several windows. */
  private sendToUser(userId: string, event: ServerPresenceEvent): void {
    for (const socket of this.server?.clients ?? []) {
      if (this.state.get(socket)?.userId === userId) this.send(socket, event);
    }
  }

  /**
   * Sends to the sockets whose user is in `audience`, and to nobody else.
   *
   * The audience is worked out once per event rather than once per socket,
   * which is what the symmetry in `audience.ts` buys: the set of people allowed
   * to hear about a user is the set that user is allowed to hear about.
   *
   * `exceptUserId` keeps a typing indicator from echoing to its own author.
   */
  private async broadcastTo(
    audience: Promise<Set<string>>,
    event: ServerPresenceEvent,
    exceptUserId?: string,
  ): Promise<void> {
    let allowed: Set<string>;
    try {
      allowed = await audience;
    } catch (error) {
      // A database that cannot answer must not turn into a broadcast to
      // everybody. Dropping the event is the safe direction: a dot is stale,
      // rather than shown to somebody with no right to it.
      this.logger.warn('Could not scope a presence event', { reason: String(error) });
      return;
    }

    for (const socket of this.server?.clients ?? []) {
      const state = this.state.get(socket);
      if (!state) continue;
      if (exceptUserId && state.userId === exceptUserId) continue;
      if (!allowed.has(state.userId)) continue;
      this.send(socket, event);
    }
  }

  private send(socket: WebSocket, event: ServerPresenceEvent): void {
    if (socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify(event));
  }

  onModuleDestroy(): void {
    if (this.heartbeat) clearInterval(this.heartbeat);
    this.server?.close();
  }
}

/**
 * Presence over HTTP, for the services that need a number rather than a stream.
 *
 * `server-service` has to answer "how many of this server's members are here
 * right now" when it describes an invite, and it has no business reading
 * presence out of Redis itself: presence belongs to this service, and a second
 * reader of `presence:online` is a second thing to change when that key does.
 *
 * It is not routed by the gateway. Nginx forwards the paths it names and
 * nothing else, and `/api/v1/internal` is not one of them, so this is reachable
 * on the internal Docker network and nowhere else. That is also why there is no
 * guard: there is no user here to authenticate, only another service.
 */
import { Controller, Get, Query } from '@nestjs/common';
import { PresenceStore } from './presence.store';

@Controller('internal/presence')
export class PresenceController {
  constructor(private readonly store: PresenceStore) {}

  /**
   * Everyone online, as ids. Invisible users are already resolved to offline by
   * the store, so they are not in this list - being counted as present is
   * exactly what invisible means you are not.
   */
  /**
   * Which of these users is reading this channel right now.
   *
   * `notification-service` asks once per message, with the audience it has
   * already worked out, and drops the answer from the fan-out: a phone is not
   * worth waking for a conversation its owner is reading on a laptop. The
   * userIds come as one comma-separated parameter because a fan-out is a batch
   * and a request per recipient would be a request per recipient.
   *
   * Empty answer for an empty or missing list, which is the honest reading of
   * "none of nobody is looking".
   */
  @Get('focus')
  async focus(
    @Query('channelId') channelId?: string,
    @Query('userIds') userIds?: string,
  ): Promise<{ focused: string[] }> {
    const audience = (userIds ?? '').split(',').filter(Boolean);
    if (!channelId || audience.length === 0) return { focused: [] };
    return { focused: await this.store.focusedAmong(channelId, audience) };
  }

  @Get('online')
  async online(): Promise<{ userIds: string[] }> {
    const states = await this.store.onlineUsers();
    return { userIds: states.map((state) => state.userId) };
  }
}

import { Body, Controller, Get, Param, Patch, Post, UseGuards } from '@nestjs/common';
import { CurrentUser, JwtAuthGuard, type AuthenticatedUser } from '@betweenus/auth';
import type {
  ChannelReadReceipt,
  ChannelUnread,
  NotificationPreferences,
} from '@betweenus/shared-types';
import { NotificationsService } from './notifications.service';
import { MarkReadDto, UpdatePreferencesDto } from './dto';

@Controller('notifications')
@UseGuards(JwtAuthGuard)
export class NotificationsController {
  constructor(private readonly notifications: NotificationsService) {}

  @Get('preferences')
  preferences(@CurrentUser() user: AuthenticatedUser): Promise<NotificationPreferences> {
    return this.notifications.preferences(user.id);
  }

  @Patch('preferences')
  updatePreferences(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: UpdatePreferencesDto,
  ): Promise<NotificationPreferences> {
    return this.notifications.updatePreferences(user.id, dto);
  }

  @Get('unread')
  unread(@CurrentUser() user: AuthenticatedUser): Promise<ChannelUnread[]> {
    return this.notifications.unread(user.id);
  }

  /** Who else has read this channel - the receipts a "seen by" row is drawn from. */
  @Get('channels/:channelId/reads')
  receipts(
    @CurrentUser() user: AuthenticatedUser,
    @Param('channelId') channelId: string,
  ): Promise<ChannelReadReceipt[]> {
    return this.notifications.receipts(user.id, channelId);
  }

  @Post('read')
  markRead(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: MarkReadDto,
  ): Promise<ChannelUnread> {
    return this.notifications.markRead(user.id, dto.channelId);
  }
}

/**
 * `/ws/remote`: the relay between a controller and an agent.
 *
 * Two kinds of socket connect here and they authenticate differently. An agent
 * presents the token it was given at enrolment (`?agent=`); a controller
 * presents the usual access token and the session it was issued (`?sessionId=`).
 * Neither ever learns the other's address - the agent dialled out, the
 * controller dialled in, and this process is the only thing that sees both.
 *
 * Every input event is checked against the permissions frozen on the session
 * row, here, on the server. The desktop client hides what it cannot do, but
 * hiding is not enforcement.
 *
 * The two halves of a session need not be on the same instance: the agent
 * dialled out hours ago and the controller dialled in just now, through a load
 * balancer with no idea they belong together. So every message goes through
 * `toAgent` / `toController`, which deliver to a local socket when this instance
 * holds it and publish through `RemoteRelay` when it does not. Nothing in this
 * file may reach into `agents` or `controllers` directly to send.
 *
 * The one consequence worth naming: a controller's live permissions cannot be
 * read from memory when the controller is somebody else's socket. They are read
 * from the session row instead, which is the authoritative copy anyway - the
 * in-memory list is a cache of it, kept in step by `control.changed`.
 */
import { Injectable, OnModuleDestroy } from '@nestjs/common';
import { randomUUID } from 'node:crypto';
import type { IncomingMessage, Server as HttpServer } from 'node:http';
import { WebSocket, WebSocketServer } from 'ws';
import { envOr } from '@betweenus/config';
import { asRemotePermissions, prisma, recordRemoteAudit } from '@betweenus/database';
import { EventBus } from '@betweenus/events';
import { Logger } from '@betweenus/logger';
import { PERMISSIONS, type RemotePermission } from '@betweenus/permissions';
import {
  SIGNAL_MAX_PAYLOAD,
  authenticateHandshake,
  dropRevokedSockets,
} from '@betweenus/websocket';
import {
  REMOTE_TRANSFER_MAX_BYTES,
  type AgentRemoteEvent,
  type ClientRemoteEvent,
  type ServerRemoteEvent,
} from '@betweenus/shared-types';
import { RemoteService } from './modules/remote/remote.service';
import { RemoteRelay, type RelayTarget } from './remote.relay';

const HEARTBEAT_INTERVAL_MS = 30_000;

/** What a controller's event needs before it is relayed to the machine. */
const REQUIRED_PERMISSION: Record<string, RemotePermission> = {
  'input.mouse': PERMISSIONS.REMOTE_CONTROL,
  'input.key': PERMISSIONS.REMOTE_CONTROL,
  'clipboard.set': PERMISSIONS.REMOTE_CLIPBOARD,
  // `file.offer` is deliberately not here. It needs `REMOTE_FILE_TRANSFER`
  // like the rest, but it is also audited and size-checked, so it is handled
  // before this table is reached - and an entry here as well would be dead
  // code that reads like the thing doing the work.
};

interface AgentSocket {
  kind: 'agent';
  machineId: string;
  ownerId: string;
  alive: boolean;
}

interface ControllerSocket {
  kind: 'controller';
  sessionId: string;
  machineId: string;
  userId: string;
  username: string;
  /** `iat` of the token that opened this socket. See `dropRevokedSockets`. */
  issuedAt: number;
  /**
   * Mutable, unlike the row it started from: the machine can lend control
   * mid-session and take it back. Every change is written to the session row
   * too, so the audit trail and a restart agree with what the relay enforces -
   * and so an instance that does not hold this socket can still read what this
   * session may do.
   */
  permissions: RemotePermission[];
  alive: boolean;
}

type SocketState = AgentSocket | ControllerSocket;

@Injectable()
export class RemoteGateway implements OnModuleDestroy {
  private server: WebSocketServer | null = null;
  private heartbeat: NodeJS.Timeout | null = null;
  private readonly state = new WeakMap<WebSocket, SocketState>();
  /** machineId -> the agent's live socket *on this instance*. */
  private readonly agents = new Map<string, WebSocket>();
  /** sessionId -> the controller's live socket *on this instance*. */
  private readonly controllers = new Map<string, WebSocket>();
  private readonly relay = new RemoteRelay(
    envOr('REDIS_URL', 'redis://localhost:6379'),
    randomUUID(),
  );

  constructor(
    private readonly remote: RemoteService,
    private readonly events: EventBus,
    private readonly logger: Logger,
  ) {}

  /**
   * The controller sockets this instance holds for one account.
   *
   * Controllers only. An agent socket is authenticated by the machine's own
   * token rather than by anybody's session, so a session revocation has nothing
   * to say about it - and dropping it would take a machine offline every time
   * its owner changed their password, which is a different feature with a
   * different answer.
   */
  private socketsOf(userId: string): WebSocket[] {
    return [...(this.server?.clients ?? [])].filter((socket) => {
      const state = this.state.get(socket);
      return state?.kind === 'controller' && state.userId === userId;
    });
  }

  attach(httpServer: HttpServer): void {
    this.remote.setPresence({
      isOnline: (machineId) => this.relay.isAgentOnline(machineId),
      onlineAmong: (machineIds) => this.relay.onlineAgents(machineIds),
    });
    this.remote.onGrantRevoked = (machineId, userId) => this.endSessionsFor(machineId, userId);
    this.remote.onSessionEnded = async (sessionId, machineId, reason) => {
      this.tearDown(sessionId, machineId, reason);
    };

    void this.relay.start((message) => this.deliverLocal(message.target, message.event, message.close));

    // A remote session belonging to an account that has just been disabled is
    // the socket it matters most to close: it is a live hand on somebody's
    // desktop. Dropping the controller ends the session through the same path
    // an ordinary disconnect does.
    void dropRevokedSockets(
      this.events,
      (userId) => this.socketsOf(userId),
      (socket) => {
        const state = this.state.get(socket);
        return state?.kind === 'controller' ? state.issuedAt : undefined;
      },
      (socket, code, reason) => socket.close(code, reason),
      (userId, count, reason) => this.logger.info('Sockets revoked', { userId, count, reason }),
    );

    this.server = new WebSocketServer({
      server: httpServer,
      path: '/ws/remote',
      maxPayload: SIGNAL_MAX_PAYLOAD,
    });

    this.server.on('connection', (socket, request) => {
      void this.onConnection(socket, request);
    });

    this.heartbeat = setInterval(() => {
      for (const socket of this.server?.clients ?? []) {
        const state = this.state.get(socket);
        if (!state) continue;
        if (!state.alive) {
          socket.terminate();
          continue;
        }
        state.alive = false;
        socket.ping();
        if (state.kind === 'agent') {
          void this.remote.touchMachine(state.machineId);
          // Renews the registry entry. It outlives two missed beats and no more,
          // so an instance that dies stops claiming its agents by itself.
          void this.relay.announceAgent(state.machineId);
        }
      }
    }, HEARTBEAT_INTERVAL_MS);

    this.logger.info('Remote WebSocket gateway ready', { path: '/ws/remote' });
  }

  private async onConnection(socket: WebSocket, request: IncomingMessage): Promise<void> {
    const url = new URL(request.url ?? '/', 'http://localhost');
    const agentToken = url.searchParams.get('agent');

    if (agentToken) {
      await this.acceptAgent(socket, agentToken);
      return;
    }
    await this.acceptController(socket, request, url.searchParams.get('sessionId'));
  }

  // --- Agents ---------------------------------------------------------------

  private async acceptAgent(socket: WebSocket, token: string): Promise<void> {
    const machine = await this.remote.machineForAgentToken(token);
    if (!machine) {
      socket.close(4401, 'Unauthorized');
      return;
    }

    // One agent per machine. A second connection is the same machine coming
    // back after a network drop, so the older socket is the stale one - and it
    // may be a socket on another instance, which is why the close is relayed
    // rather than only applied here.
    const previous = this.agents.get(machine.id);
    if (previous && previous !== socket) previous.close(4409, 'Replaced');

    this.agents.set(machine.id, socket);
    this.state.set(socket, {
      kind: 'agent',
      machineId: machine.id,
      ownerId: machine.ownerId,
      alive: true,
    });
    await this.remote.touchMachine(machine.id);
    // Claimed before the older socket elsewhere is told to go: the registry
    // should never have a window where the machine reads offline.
    await this.relay.announceAgent(machine.id);
    await this.relay.forward({ kind: 'agent', machineId: machine.id }, null, {
      code: 4409,
      reason: 'Replaced',
    });

    this.send(socket, { type: 'ready', role: 'agent', machineId: machine.id });
    this.logger.info('Remote agent connected', { machineId: machine.id });

    socket.on('pong', () => this.markAlive(socket));
    socket.on('message', (raw) => void this.onAgentEvent(socket, raw.toString()));
    socket.on('close', () => {
      // Only if this socket is still the registered one: a reconnect replaces
      // the entry before the old socket's close event arrives.
      if (this.agents.get(machine.id) !== socket) {
        this.state.delete(socket);
        return;
      }
      this.agents.delete(machine.id);
      this.state.delete(socket);
      void this.relay.forgetAgent(machine.id);
      // Every session on a machine that just went away is over; nothing is
      // going to answer for it.
      void this.endSessionsForMachine(machine.id, 'agent-offline');
      this.logger.info('Remote agent disconnected', { machineId: machine.id });
    });
    socket.on('error', (error) => {
      this.logger.warn('Remote agent socket error', {
        machineId: machine.id,
        reason: String(error),
      });
    });
  }

  private async onAgentEvent(socket: WebSocket, raw: string): Promise<void> {
    const state = this.state.get(socket);
    if (state?.kind !== 'agent') return;

    let event: AgentRemoteEvent;
    try {
      event = JSON.parse(raw) as AgentRemoteEvent;
    } catch {
      return;
    }

    switch (event.type) {
      case 'agent.ready':
        await this.remote.touchMachine(state.machineId);
        return;

      case 'session.accepted':
      case 'session.refused': {
        if (event.type === 'session.accepted') {
          this.toController(event.sessionId, {
            type: 'agent.state',
            sessionId: event.sessionId,
            state: 'accepted',
          });
          return;
        }

        this.toController(event.sessionId, {
          type: 'agent.state',
          sessionId: event.sessionId,
          state: 'refused',
          reason: event.reason,
        });
        // The person sitting at the machine said no. That is a refusal worth
        // keeping: it is the record that consent was asked for and withheld.
        await recordRemoteAudit({
          machineId: state.machineId,
          sessionId: event.sessionId,
          action: 'session.refused',
          detail: { reason: event.reason, by: 'agent' },
        });
        await this.remote.endSession(event.sessionId, 'refused');
        this.tearDown(event.sessionId, state.machineId, 'refused');
        return;
      }

      case 'session.ended':
        await this.remote.endSession(event.sessionId, 'agent');
        this.tearDown(event.sessionId, state.machineId, 'agent');
        return;

      case 'control.granted':
      case 'control.denied': {
        // Read from the session row rather than from a controller socket this
        // instance may not hold. The row is what the relay enforces against, so
        // it is also the right thing to change.
        const session = await this.liveSession(event.sessionId);
        if (!session) return;

        const granted = event.type === 'control.granted';
        const refusal = event.type === 'control.denied' ? (event.reason ?? 'declined') : null;
        let permissions = session.permissions;

        if (granted && !permissions.includes(PERMISSIONS.REMOTE_CONTROL)) {
          // Somebody at the machine said yes. That is a higher authority than a
          // stored grant, so it stands - but only for this session: it is
          // written to the session row, never to the grant.
          permissions = [...permissions, PERMISSIONS.REMOTE_CONTROL];
          await prisma.remoteSession
            .update({ where: { id: event.sessionId }, data: { permissions } })
            .catch(() => undefined);
        }

        await recordRemoteAudit({
          machineId: state.machineId,
          sessionId: event.sessionId,
          actorId: session.userId,
          action: granted ? 'control.granted' : 'control.denied',
          detail: granted ? {} : { reason: refusal },
        });

        this.toController(event.sessionId, {
          type: 'control.changed',
          sessionId: event.sessionId,
          permissions,
          granted,
          ...(granted ? {} : { reason: refusal ?? 'The machine refused' }),
        });
        return;
      }

      // Which displays the machine has. No permission of its own: a session
      // that may see the screen may know how many there are.
      case 'screens':
        this.toController(event.sessionId, {
          type: 'screens',
          screens: event.screens,
          activeId: event.activeId,
        });
        return;

      case 'clipboard.text': {
        // The machine's clipboard travelling to the controller needs the same
        // permission as the other direction.
        const session = await this.liveSession(event.sessionId);
        if (session?.permissions.includes(PERMISSIONS.REMOTE_CLIPBOARD)) {
          this.toController(event.sessionId, { type: 'clipboard.set', text: event.text });
        }
        return;
      }

      // The machine's answer to an offered file, and the receipt when the last
      // byte has landed. The `sessionId` the agent stamps is dropped here: a
      // controller holds exactly one session and has no use for it, which is
      // the same shape `screens` and `clipboard.set` already have.
      case 'file.accepted':
        this.toController(event.sessionId, {
          type: 'file.accepted',
          transferId: event.transferId,
        });
        return;

      case 'file.refused':
        this.toController(event.sessionId, {
          type: 'file.refused',
          transferId: event.transferId,
          reason: event.reason,
        });
        return;

      case 'file.done': {
        // Written down on arrival rather than on the offer, so the trail says
        // what reached the machine and not only what was aimed at it.
        const session = await this.liveSession(event.sessionId);
        await recordRemoteAudit({
          machineId: state.machineId,
          sessionId: event.sessionId,
          actorId: session?.userId ?? null,
          action: 'file.received',
          detail: { transferId: event.transferId, path: event.path },
        });
        this.toController(event.sessionId, {
          type: 'file.done',
          transferId: event.transferId,
          path: event.path,
        });
        return;
      }

      // The agent's half of setting up the peer connection, on its way to that
      // session's controller. Forwarded without being read: an SDP this gateway
      // rewrote would be an SDP it could put itself in the middle of.
      case 'rtc.signal':
        this.toController(event.sessionId, { type: 'rtc.signal', data: event.data });
        return;

      case 'pong':
        return;

      default:
        return;
    }
  }

  // --- Controllers ----------------------------------------------------------

  private async acceptController(
    socket: WebSocket,
    request: IncomingMessage,
    sessionId: string | null,
  ): Promise<void> {
    const user = authenticateHandshake(request);
    if (!user || !sessionId) {
      socket.close(4401, 'Unauthorized');
      return;
    }

    const session = await prisma.remoteSession.findUnique({
      where: { id: sessionId },
      select: {
        id: true,
        machineId: true,
        userId: true,
        permissions: true,
        endedAt: true,
        machine: { select: { name: true } },
      },
    });

    // The session is the authorization. It was issued to one person over HTTP
    // after the grant was checked; presenting somebody else's is not a way in.
    if (!session || session.endedAt || session.userId !== user.id) {
      socket.close(4403, 'Forbidden');
      return;
    }

    // Connected to any instance, not only this one.
    if (!(await this.relay.isAgentOnline(session.machineId))) {
      socket.close(4404, 'Agent offline');
      await this.remote.endSession(sessionId, 'agent-offline');
      return;
    }

    const permissions = asRemotePermissions(session.permissions);

    this.controllers.set(sessionId, socket);
    this.state.set(socket, {
      kind: 'controller',
      sessionId,
      machineId: session.machineId,
      userId: user.id,
      username: user.username,
      issuedAt: user.issuedAt,
      permissions,
      alive: true,
    });

    this.send(socket, { type: 'ready', role: 'controller', sessionId });

    // Only now does the machine hear about it: the agent is asked to consent
    // and, if it does, to offer its screen to the controller directly. It is
    // given ICE servers rather than an address, because nothing here knows or
    // needs to know where either end is.
    this.toAgent(session.machineId, {
      type: 'session.start',
      sessionId,
      controllerId: user.id,
      controllerName: user.username,
      permissions,
      iceServers: await this.remote.agentIceServers(),
    });

    this.logger.info('Remote session opened', {
      sessionId,
      machineId: session.machineId,
      userId: user.id,
    });

    socket.on('pong', () => this.markAlive(socket));
    socket.on('message', (raw) => void this.onControllerEvent(socket, raw.toString()));
    socket.on('close', () => {
      this.state.delete(socket);
      if (this.controllers.get(sessionId) === socket) this.controllers.delete(sessionId);
      void this.remote.endSession(sessionId, 'controller');
      this.toAgent(session.machineId, { type: 'session.ended', sessionId, reason: 'controller' });
    });
    socket.on('error', () => socket.close());
  }

  private async onControllerEvent(socket: WebSocket, raw: string): Promise<void> {
    const state = this.state.get(socket);
    if (state?.kind !== 'controller') return;

    let event: ClientRemoteEvent;
    try {
      event = JSON.parse(raw) as ClientRemoteEvent;
    } catch {
      return;
    }

    if (event.type === 'ping') {
      this.send(socket, { type: 'pong' });
      return;
    }

    if (event.type === 'session.end') {
      await this.remote.endSession(state.sessionId, 'controller');
      this.tearDown(state.sessionId, state.machineId, 'controller');
      return;
    }

    // Asking for control, RDP style. A session already granted it is answered
    // here and never bothers the machine; one that was not has to be let in by
    // whoever is sitting at it.
    if (event.type === 'control.request') {
      if (state.permissions.includes(PERMISSIONS.REMOTE_CONTROL)) {
        this.send(socket, {
          type: 'control.changed',
          sessionId: state.sessionId,
          permissions: state.permissions,
          granted: true,
        });
        return;
      }

      if (!(await this.requireAgent(socket, state.machineId))) return;

      await recordRemoteAudit({
        machineId: state.machineId,
        sessionId: state.sessionId,
        actorId: state.userId,
        action: 'control.requested',
      });
      this.toAgent(state.machineId, {
        type: 'control.requested',
        sessionId: state.sessionId,
        controllerName: state.username,
      });
      return;
    }

    // Handing control back mid-session. Only what the machine lent is taken
    // away - a session granted control up front keeps it.
    if (event.type === 'control.release') {
      state.permissions = state.permissions.filter(
        (permission) => permission !== PERMISSIONS.REMOTE_CONTROL,
      );
      await prisma.remoteSession
        .update({ where: { id: state.sessionId }, data: { permissions: state.permissions } })
        .catch(() => undefined);
      this.send(socket, {
        type: 'control.changed',
        sessionId: state.sessionId,
        permissions: state.permissions,
        granted: false,
      });
      this.toAgent(state.machineId, {
        type: 'control.changed',
        sessionId: state.sessionId,
        permissions: state.permissions,
        granted: false,
      });
      return;
    }

    // Choosing a monitor is a view decision, not a control one: a view-only
    // session is entitled to look at the other screen. The agent answers with a
    // fresh `screens`, so the controller never has to assume it worked.
    if (event.type === 'screen.select') {
      if (!(await this.requireAgent(socket, state.machineId))) return;
      this.toAgent(state.machineId, {
        type: 'screen.select',
        sessionId: state.sessionId,
        screenId: event.screenId,
      });
      return;
    }

    // The controller's half of setting up the peer connection, on its way to
    // the agent. No permission of its own: answering an offer is how a session
    // that may view the screen comes to see it, and REMOTE_VIEW was checked
    // before the session existed. Forwarded without being read, for the same
    // reason the other direction is.
    if (event.type === 'rtc.signal') {
      this.toAgent(state.machineId, {
        type: 'rtc.signal',
        sessionId: state.sessionId,
        data: event.data,
      });
      return;
    }

    // Giving up on a transfer needs no permission of its own. Refusing it
    // would leave the machine writing a file nobody is still sending, which is
    // worse than letting a session that may not send files cancel one it never
    // started.
    if (event.type === 'file.cancel') {
      if (!(await this.requireAgent(socket, state.machineId))) return;
      this.toAgent(state.machineId, event);
      return;
    }

    // A file arriving on a machine is the event somebody reads the trail for
    // afterwards, so it is written down before it is allowed rather than
    // counted in the bytes that never come past here. The size is what the
    // controller claims; the machine counts the bytes itself.
    if (event.type === 'file.offer') {
      if (!state.permissions.includes(PERMISSIONS.REMOTE_FILE_TRANSFER)) {
        await this.refuse(socket, state, event.type, PERMISSIONS.REMOTE_FILE_TRANSFER);
        return;
      }
      if (
        !Number.isSafeInteger(event.size) ||
        event.size <= 0 ||
        event.size > REMOTE_TRANSFER_MAX_BYTES
      ) {
        this.send(socket, {
          type: 'file.refused',
          transferId: event.transferId,
          reason: 'That file is too big to send',
        });
        return;
      }
      if (!(await this.requireAgent(socket, state.machineId))) return;
      await recordRemoteAudit({
        machineId: state.machineId,
        sessionId: state.sessionId,
        actorId: state.userId,
        action: 'file.offered',
        detail: { name: event.name, size: event.size, transferId: event.transferId },
      });
      this.toAgent(state.machineId, event);
      return;
    }

    const required = REQUIRED_PERMISSION[event.type];
    if (!required) {
      this.send(socket, { type: 'error', code: 'UNKNOWN_EVENT', message: 'Unsupported event' });
      return;
    }

    if (!state.permissions.includes(required)) {
      await this.refuse(socket, state, event.type, required);
      return;
    }

    if (!(await this.requireAgent(socket, state.machineId))) return;
    this.toAgent(state.machineId, event as ServerRemoteEvent);
  }

  /**
   * Says no to one event, and writes down that it said no.
   *
   * Refusals are audited, not only rejected: a client that keeps asking for
   * something it was not granted is worth being able to see afterwards. Every
   * path that turns an event away goes through here, so a new permission cannot
   * arrive with a refusal that leaves no trace.
   */
  private async refuse(
    socket: WebSocket,
    state: ControllerSocket,
    event: string,
    required: RemotePermission,
  ): Promise<void> {
    this.send(socket, {
      type: 'error',
      code: `${required}_REQUIRED`,
      message: 'That is not permitted in this session',
    });
    await recordRemoteAudit({
      machineId: state.machineId,
      sessionId: state.sessionId,
      actorId: state.userId,
      action: 'input.refused',
      detail: { event, required },
    });
  }

  // --- Delivery -------------------------------------------------------------

  /** Local socket if this instance holds it, the relay otherwise. */
  private toAgent(
    machineId: string,
    event: ServerRemoteEvent,
    close?: { code: number; reason: string },
  ): void {
    const target: RelayTarget = { kind: 'agent', machineId };
    if (this.agents.has(machineId)) {
      this.deliverLocal(target, event, close);
      return;
    }
    void this.relay.forward(target, event, close);
  }

  private toController(
    sessionId: string,
    event: ServerRemoteEvent,
    close?: { code: number; reason: string },
  ): void {
    const target: RelayTarget = { kind: 'controller', sessionId };
    if (this.controllers.has(sessionId)) {
      this.deliverLocal(target, event, close);
      return;
    }
    void this.relay.forward(target, event, close);
  }

  /**
   * The one place a message reaches a socket, whether it came from this
   * instance or another one - which is what makes the cached copy of a
   * session's permissions impossible to get out of step: `control.changed` is
   * applied here, on the way past, wherever the controller happens to be.
   */
  private deliverLocal(
    target: RelayTarget,
    event: ServerRemoteEvent | null,
    close?: { code: number; reason: string },
  ): void {
    const socket =
      target.kind === 'agent'
        ? this.agents.get(target.machineId)
        : this.controllers.get(target.sessionId);
    if (!socket) return;

    if (target.kind === 'controller' && event?.type === 'control.changed') {
      const state = this.state.get(socket);
      if (state?.kind === 'controller') state.permissions = asRemotePermissions(event.permissions);
    }

    if (event) this.send(socket, event);
    if (close) socket.close(close.code, close.reason);
  }

  /** The session as the server holds it, or null if it is over. */
  private async liveSession(
    sessionId: string,
  ): Promise<{ userId: string; permissions: RemotePermission[] } | null> {
    const session = await prisma.remoteSession.findUnique({
      where: { id: sessionId },
      select: { userId: true, permissions: true, endedAt: true },
    });
    if (!session || session.endedAt) return null;
    return { userId: session.userId, permissions: asRemotePermissions(session.permissions) };
  }

  /** Tells the controller when the machine is not there, and answers whether it is. */
  private async requireAgent(socket: WebSocket, machineId: string): Promise<boolean> {
    if (await this.relay.isAgentOnline(machineId)) return true;
    this.send(socket, { type: 'error', code: 'AGENT_OFFLINE', message: 'The machine is gone' });
    return false;
  }

  // --- Teardown -------------------------------------------------------------

  /** Closes both ends of a session that is over, whoever ended it. */
  private tearDown(sessionId: string, machineId: string, reason: string): void {
    this.toController(sessionId, { type: 'session.ended', sessionId, reason }, {
      code: 4000,
      reason,
    });
    // The agent has to stop capturing whether or not the controller is still
    // there to be told - a session nobody is watching must not stay open.
    this.toAgent(machineId, { type: 'session.ended', sessionId, reason });
  }

  /** Every live session on a machine, for when its agent disappears. */
  private async endSessionsForMachine(machineId: string, reason: string): Promise<void> {
    const open = await prisma.remoteSession.findMany({
      where: { machineId, endedAt: null },
      select: { id: true },
    });
    for (const session of open) {
      await this.remote.endSession(session.id, reason);
      this.tearDown(session.id, machineId, reason);
    }
  }

  /**
   * A revoked grant takes effect immediately, including on a session already
   * running. Permissions are frozen when a session starts precisely so that
   * this is a decision rather than a race.
   */
  private async endSessionsFor(machineId: string, userId: string): Promise<void> {
    const open = await prisma.remoteSession.findMany({
      where: { machineId, userId, endedAt: null },
      select: { id: true },
    });
    for (const session of open) {
      await this.remote.endSession(session.id, 'revoked');
      this.tearDown(session.id, machineId, 'revoked');
    }
  }

  private markAlive(socket: WebSocket): void {
    const state = this.state.get(socket);
    if (state) state.alive = true;
  }

  private send(socket: WebSocket, event: ServerRemoteEvent): void {
    if (socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify(event));
  }

  async onModuleDestroy(): Promise<void> {
    if (this.heartbeat) clearInterval(this.heartbeat);
    this.server?.close();
    await this.relay.close();
  }
}

import {
  Body,
  Controller,
  Delete,
  Get,
  Headers,
  HttpCode,
  Param,
  ParseUUIDPipe,
  Patch,
  Post,
  Put,
  Query,
  UseGuards,
} from '@nestjs/common';
import { CurrentUser, JwtAuthGuard, type AuthenticatedUser } from '@betweenus/auth';
import type {
  EnrolMachineResponse,
  RemoteAuditEntry,
  RemoteGrantSummary,
  RemoteMachineSummary,
  RemoteSessionResponse,
} from '@betweenus/shared-types';
import { RemoteService } from './remote.service';
import {
  EnrolMachineDto,
  RenameMachineDto,
  SetRemoteGrantDto,
  StartRemoteSessionDto,
} from './dto';

/**
 * `/api/v1/remote`. Thin: every rule lives in RemoteService, and the socket
 * gateway is what carries a live session.
 */
@Controller('remote')
@UseGuards(JwtAuthGuard)
export class RemoteController {
  constructor(private readonly remote: RemoteService) {}

  @Get('machines')
  machines(@CurrentUser() user: AuthenticatedUser): Promise<RemoteMachineSummary[]> {
    return this.remote.machines(user.id);
  }

  /** The agent calls this once, signed in as the person who owns the machine. */
  @Post('machines')
  enrol(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: EnrolMachineDto,
  ): Promise<EnrolMachineResponse> {
    return this.remote.enrol(user.id, dto);
  }

  @Patch('machines/:machineId')
  rename(
    @CurrentUser() user: AuthenticatedUser,
    @Param('machineId', ParseUUIDPipe) machineId: string,
    @Body() dto: RenameMachineDto,
  ): Promise<RemoteMachineSummary> {
    return this.remote.rename(user.id, machineId, dto.name);
  }

  @Delete('machines/:machineId')
  @HttpCode(204)
  remove(
    @CurrentUser() user: AuthenticatedUser,
    @Param('machineId', ParseUUIDPipe) machineId: string,
  ): Promise<void> {
    return this.remote.remove(user.id, machineId);
  }

  @Get('machines/:machineId/grants')
  grants(
    @CurrentUser() user: AuthenticatedUser,
    @Param('machineId', ParseUUIDPipe) machineId: string,
  ): Promise<RemoteGrantSummary[]> {
    return this.remote.grants(user.id, machineId);
  }

  /** One call sets or revokes; an empty permission list is the revocation. */
  @Put('machines/:machineId/grants')
  setGrant(
    @CurrentUser() user: AuthenticatedUser,
    @Param('machineId', ParseUUIDPipe) machineId: string,
    @Body() dto: SetRemoteGrantDto,
  ): Promise<RemoteGrantSummary[]> {
    return this.remote.setGrant(user.id, machineId, dto);
  }

  @Get('machines/:machineId/audit')
  audit(
    @CurrentUser() user: AuthenticatedUser,
    @Param('machineId', ParseUUIDPipe) machineId: string,
    @Query('limit') limit?: string,
  ): Promise<RemoteAuditEntry[]> {
    // `?limit=abc` is NaN, and NaN survives the service's clamp all the way to
    // the query. Anything that is not a number is no answer at all.
    const parsed = limit === undefined ? undefined : Number(limit);
    return this.remote.audit(
      user.id,
      machineId,
      parsed !== undefined && Number.isFinite(parsed) ? parsed : undefined,
    );
  }

  @Post('sessions')
  start(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: StartRemoteSessionDto,
  ): Promise<RemoteSessionResponse> {
    // No `Host` header is read here any more. It existed so the reply could
    // refuse to name a media server this caller could not dial; the reply names
    // no server at all now, so there is nothing about where they are that could
    // make it wrong.
    return this.remote.startSession(user, dto.machineId);
  }

  /**
   * Ending over HTTP as well as over the socket: a window that was closed
   * without a clean disconnect still has to be able to say the session is over.
   */
  @Delete('sessions/:sessionId')
  @HttpCode(204)
  async end(
    @CurrentUser() user: AuthenticatedUser,
    @Param('sessionId', ParseUUIDPipe) sessionId: string,
  ): Promise<void> {
    await this.remote.endSessionFor(user.id, sessionId, 'controller');
  }
}

package com.aatech.betweenus.core.crypto

import android.content.Context
import com.aatech.betweenus.core.data.ApiError
import com.aatech.betweenus.core.data.ChannelKeyEntry
import com.aatech.betweenus.core.data.ChannelKeys
import com.aatech.betweenus.core.data.DeviceKey
import com.aatech.betweenus.core.data.IdentityBackup
import com.aatech.betweenus.core.data.StatusEntry
import com.aatech.betweenus.core.data.StatusKeyEntry
import com.aatech.betweenus.core.data.BetweenUsApi
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import org.json.JSONObject
import java.util.concurrent.ConcurrentHashMap

/** What opens an identity backup. Held only for the moment a sign-in needs it. */
data class BackupSecret(val value: String, val kind: String) {
    companion object {
        fun password(value: String) = BackupSecret(value, "password")
        fun passphrase(value: String) = BackupSecret(value, "passphrase")
    }
}

class MissingChannelKeyError : Exception("No channel key on this device yet")

/**
 * There is no `Locked`. A device that cannot open the account backup mints a
 * key of its own and signs in anyway - see [E2ee.initIdentity] - so there is no
 * state in which the app is signed in and waiting to be told a secret. That
 * fork used to be permanent; it is provisional now, and every later sign-in
 * with a secret that opens the backup undoes it.
 */
sealed interface IdentityStatus {
    data object Absent : IdentityStatus

    /**
     * `backedUp` is whether *this device's* key is the one in the backup.
     *
     * `provisional` is this device having minted its own because it could not
     * open the account's - so it reads what arrives from now on, and history is
     * still sealed to an identity it does not hold.
     */
    data class Ready(val backedUp: Boolean, val provisional: Boolean = false) : IdentityStatus

    /**
     * The owner revoked this machine from another one. Nothing new is wrapped
     * for it, so it reads what it already had and nothing since - saying so
     * beats a screen full of "no key on this device yet".
     */
    data object Revoked : IdentityStatus
}

/**
 * The end-to-end encryption service: this device's identity, the channel keys
 * it can open, and sealing and opening content with them.
 *
 * The port of `apps/desktop/src/services/e2ee.ts`. Every decision here about
 * *when* to mint an epoch, when to re-wrap for a member, and what to do when a
 * key cannot be opened is that file's, because the three clients share one
 * channel and disagreeing about any of it locks somebody out of their history.
 */
object E2ee {
    /**
     * Shown instead of a message this device holds no key for.
     *
     * Two words: it is drawn once per message, and a sentence repeated down a
     * whole screen is not eight times as informative as one. Why, and what to
     * do about it, is said once for the channel.
     */
    const val UNDECRYPTABLE = "🔒 Encrypted"

    private lateinit var store: SecureStore

    private var identity: Crypto.KeyPairJwk? = null
    private var userId: String? = null

    /**
     * The secret this session signed in with, kept for the length of the session.
     *
     * It used to be an argument and nothing else, so a sign-in whose identity
     * setup failed once - the network dropped, the token was a moment late -
     * lost it. [currentIdentity] then retried with no secret, could not open the
     * account backup, and minted a device-local key instead, which was
     * permanent. A password typed into a login form is dropped when the session
     * ends, and that is the only thing keeping it here has to guarantee.
     */
    @Volatile
    private var signInSecret: BackupSecret? = null

    private val identityLock = Mutex()
    private val channelLocks = ConcurrentHashMap<String, Mutex>()

    /** Every epoch this device can open, per channel, so old history stays readable. */
    private class ChannelKeyState(val epoch: Int, val keys: Map<Int, String>)

    private val channels = ConcurrentHashMap<String, ChannelKeyState>()

    /**
     * Channels this session has already tried to re-key for itself. Without it,
     * a device that cannot open its own wrapped keys would mint a fresh epoch
     * every time the channel is opened and drag the whole channel along with it.
     */
    private val rekeyed = ConcurrentHashMap.newKeySet<String>()

    /**
     * Epochs this client has already gone back to the directory for and still
     * not found. Without it, a channel holding one genuinely unreadable message
     * would re-read the key directory every time that message is drawn.
     */
    private val missedEpochs = ConcurrentHashMap.newKeySet<String>()

    private val _status = MutableStateFlow<IdentityStatus>(IdentityStatus.Absent)
    val status: StateFlow<IdentityStatus> = _status.asStateFlow()

    fun init(context: Context) {
        store = SecureStore(context)
    }

    // --- identity ---

    /**
     * Loads this device's identity key and publishes the public half. Called
     * once per sign-in, with the password when there is one to hand.
     *
     * It never fails for want of a secret, and it never asks for one.
     */
    suspend fun initIdentity(userId: String, secret: BackupSecret? = null): Crypto.KeyPairJwk =
        identityLock.withLock {
            identity?.let { if (this.userId == userId) return@withLock it }
            this.userId = userId
            // Held past this call on purpose: [currentIdentity] retries with no
            // secret of its own, and a retry without one forks permanently.
            if (secret != null) signInSecret = secret
            val opener = secret ?: signInSecret

            val storageKey = "identity:$userId"
            store.get(storageKey)?.let { stored ->
                val saved = runCatching { readStored(stored) }.getOrNull()
                if (saved != null) {
                    // A device that forked gets another go, every time a secret
                    // is at hand. This is the whole of "sign in on a new phone
                    // and your messages are there": the fork below is silent and
                    // one-way, so the only thing that makes it recoverable is
                    // trying the backup again on the next sign-in rather than
                    // short-circuiting on the key the fork left behind.
                    if (saved.provisional && opener != null) {
                        restoreFromBackup(storageKey, opener)?.let { return@withLock it }
                    }
                    adopt(saved.pair, provisional = saved.provisional)
                    // A device that already worked may still have no backup.
                    // Fix it quietly when a secret is at hand rather than
                    // waiting for the next reinstall to notice.
                    ensureBackup(saved.pair, opener)
                    return@withLock saved.pair
                }
            }

            // A failed fetch must not be read as "there is no backup": that
            // would seal a fresh key over one that exists. It throws, and the
            // sign-in retries.
            val backups = BetweenUsApi.identityBackups()

            // The account's own key, when the secret that opens it is at hand.
            // The good path and the only instant one: every epoch already
            // sealed for that identity opens the moment it lands.
            if (opener != null) {
                restoreFromBackup(storageKey, opener, backups)?.let { return@withLock it }
            }

            // Otherwise this device gets a key of its own and the sign-in
            // carries on. It used to stop and ask - and asking is not something
            // every sign-in can answer: a provider sign-in has no account
            // password to offer, and an account that has only ever used one has
            // no password at all.
            //
            // Minting is safe because a channel key is wrapped per *device*:
            // this device publishes its own public key under its own device id
            // and takes nothing from the devices already in the directory.
            // History arrives from them - `fillGaps` hands every epoch a device
            // holds to the owner's devices missing it - so the account
            // converges without anyone typing anything. What it costs is that
            // history is not instant; it appears as the other devices open
            // those channels. See apps/desktop/src/services/e2ee.ts.
            //
            // The fork is marked when the account *had* a backup this device
            // could not open, and that mark is what lets the next sign-in undo
            // it. Unmarked means there was nothing to restore from, so this key
            // is the account's own.
            val provisional = backups.isNotEmpty()
            val pair = Crypto.generateIdentity()
            store.put(storageKey, writePair(pair, provisional))
            adopt(pair, provisional = provisional)
            ensureBackup(pair, opener)
            pair
        }

    /**
     * Opens whichever backup [secret] fits and makes it this device's identity.
     *
     * Null means "not this secret" - a wrong password, or a passphrase-only
     * account signing in with a password - which is an ordinary outcome here,
     * not a failure.
     *
     * Every channel key held on this device is dropped on the way out. They are
     * still valid, but they are the *subset* a forked identity could reach, and
     * the caches in front of them - memory and the sealed store both - would
     * keep serving that subset while the wraps this identity can now open sat
     * unread in the directory. Dropping them costs one re-read of a directory
     * we have just been talking to.
     */
    private suspend fun restoreFromBackup(
        storageKey: String,
        secret: BackupSecret,
        known: List<IdentityBackup>? = null,
    ): Crypto.KeyPairJwk? {
        val backups = known ?: runCatching { BetweenUsApi.identityBackups() }.getOrNull() ?: return null
        val sealed = backups.firstOrNull { it.kind == secret.kind } ?: return null
        val pair = openBackup(sealed, secret) ?: return null

        store.put(storageKey, writePair(pair))
        forgetAllKeys()
        adopt(pair, backedUp = true)
        return pair
    }

    /** Seals the current identity under a secret the user chose. */
    suspend fun backupIdentity(secret: BackupSecret) {
        val pair = currentIdentity()
        BetweenUsApi.putIdentityBackup(seal(pair, secret))
        _status.value = IdentityStatus.Ready(backedUp = true)
    }

    /**
     * Re-seals the backup after a password change. Skipped silently when the
     * backup is keyed to a passphrase, which a password change does not touch.
     */
    suspend fun rewrapBackupForPassword(newPassword: String) {
        if (BetweenUsApi.identityBackups().none { it.kind == "password" }) return
        backupIdentity(BackupSecret.password(newPassword))
        // The secret this session holds is now the old one, and a retry using it
        // would fail to open the blob it has just re-sealed.
        signInSecret = BackupSecret.password(newPassword)
    }

    /**
     * Whether the account password can still recover this identity on a device
     * that has never seen it.
     *
     * The one thing a settings screen has to be able to say plainly: it is the
     * difference between "sign in anywhere" and "sign in anywhere and type a
     * passphrase you wrote down once".
     */
    suspend fun passwordRecoveryEnabled(): Boolean =
        BetweenUsApi.identityBackups().any { it.kind == "password" }

    /**
     * Turns the password path off, for somebody who set a recovery passphrase
     * *because* a live server sees the password at sign-in and they would rather
     * it could never open the backup.
     *
     * Refuses when it would leave the account with no backup at all. That is not
     * a security setting, it is losing every message on the next reinstall.
     */
    suspend fun disablePasswordRecovery() {
        if (BetweenUsApi.identityBackups().none { it.kind == "passphrase" }) {
            error("Set a recovery passphrase first, or this account has no way back at all")
        }
        BetweenUsApi.deleteIdentityBackup("password")
    }

    fun reset() {
        // Key material is per-user; a sign-out must not leak it into the next
        // session. What is on disk stays - it is sealed, and the same account
        // signing back in should not have to fetch its backup again.
        identity = null
        userId = null
        signInSecret = null
        channels.clear()
        channelLocks.clear()
        rekeyed.clear()
        missedEpochs.clear()
        _status.value = IdentityStatus.Absent
    }

    private suspend fun adopt(
        pair: Crypto.KeyPairJwk,
        backedUp: Boolean = false,
        provisional: Boolean = false,
    ) {
        identity = pair
        try {
            // Idempotent: re-publishing keeps the directory correct if the row
            // was lost, and refreshes when this phone was last seen.
            BetweenUsApi.registerDeviceKey(DeviceIdentity.id(), pair.publicKey, DeviceIdentity.label())
        } catch (error: ApiError) {
            // Revoked from another machine. Not a thing to retry, and not a
            // reason to mint a new id - minting one is how a revoked phone
            // would walk straight back into the directory.
            if (error.code == "DEVICE_REVOKED") {
                _status.value = IdentityStatus.Revoked
            }
            throw error
        }
        _status.value = IdentityStatus.Ready(backedUp, provisional)
    }

    /**
     * Uploads a backup when the account has none for this identity and a secret
     * is available to seal it with. Never throws into a sign-in: an account
     * without a backup still works, it is only unrecoverable, and settings says so.
     */
    private suspend fun ensureBackup(pair: Crypto.KeyPairJwk, secret: BackupSecret?) {
        runCatching {
            val backups = BetweenUsApi.identityBackups()
            val backedUp = backups.any { it.publicKey == pair.publicKey }

            // A backup that already stands is not this device's to replace
            // unless it is this device's key in it. Since a device that could
            // not open one mints its own, sealing over it here would take the
            // account's recoverable identity away from every device still
            // restoring from it. Deliberate re-sealing is [backupIdentity]'s.
            //
            // Scoped to the *kind* now. An account holding a passphrase backup
            // and no password one is exactly the account that cannot recover on
            // a fresh sign-in, so filling that gap when the password is at hand
            // is the point rather than an overreach - and it only ever seals the
            // key this device already holds, which is the identity the other
            // devices restore from whenever `backedUp` says so.
            if (secret == null || backups.any { it.kind == secret.kind } || !backedUp) {
                _status.value = IdentityStatus.Ready(
                    backedUp = backedUp,
                    provisional = backups.isNotEmpty() && !backedUp,
                )
                return
            }
            BetweenUsApi.putIdentityBackup(seal(pair, secret))
            _status.value = IdentityStatus.Ready(backedUp = true)
        }
        // Offline, or a server older than this client. Nothing is lost that was
        // not already missing.
    }

    private fun seal(pair: Crypto.KeyPairJwk, secret: BackupSecret): IdentityBackup {
        val (salt, iv, ct) = Crypto.sealIdentity(pair, secret.value)
        return IdentityBackup(
            kind = secret.kind,
            iterations = Crypto.BACKUP_ITERATIONS,
            salt = salt,
            iv = iv,
            ct = ct,
            publicKey = pair.publicKey,
        )
    }

    /** The wrong secret is an ordinary outcome here, not an error: null, and on. */
    private fun openBackup(backup: IdentityBackup, secret: BackupSecret): Crypto.KeyPairJwk? =
        runCatching {
            Crypto.openIdentity(backup.salt, backup.iv, backup.ct, secret.value, backup.iterations)
        }.getOrNull()

    /**
     * What the sealed store holds. `provisional` marks a key this device minted
     * for itself *while the account had a backup it could not open* - the fork
     * described in [initIdentity]. It is the flag that makes the fork
     * recoverable: without it the stored key short-circuits every later launch
     * and the backup is never tried again, on any sign-in, ever.
     */
    private class StoredIdentity(val pair: Crypto.KeyPairJwk, val provisional: Boolean)

    private fun writePair(pair: Crypto.KeyPairJwk, provisional: Boolean = false) = JSONObject()
        .put("publicKey", pair.publicKey)
        .put("privateKey", pair.privateKey)
        .put("provisional", provisional)
        .toString()

    private fun readStored(stored: String): StoredIdentity {
        val json = JSONObject(stored)
        return StoredIdentity(
            pair = Crypto.KeyPairJwk(json.getString("publicKey"), json.getString("privateKey")),
            // Absent on a blob written before the fork was recoverable. False is
            // the safe reading: it was minted under rules that had no mark, and
            // a sign-in that opens the backup replaces it either way.
            provisional = json.optBoolean("provisional", false),
        )
    }

    private suspend fun currentIdentity(): Crypto.KeyPairJwk =
        identity
            // With the session's secret, not without it. A retry that dropped it
            // opened no backup, minted a device-local key, and forked for good.
            ?: userId?.let { initIdentity(it, signInSecret) }
            ?: throw MissingChannelKeyError()

    // --- content ---

    suspend fun encryptForChannel(channelId: String, plaintext: String): String {
        val state = ensureChannelKey(channelId)
        val key = state.keys[state.epoch] ?: throw MissingChannelKeyError()
        val sealed = Crypto.encrypt(plaintext, key)
        return JSONObject()
            .put("v", 1)
            .put("epoch", state.epoch)
            .put("iv", sealed.iv)
            .put("ct", Crypto.base64(sealed.ciphertext))
            .toString()
    }

    /**
     * Reads a stored message body. Anything that is not an envelope is returned
     * as it stands, so plaintext rows written before E2EE still render.
     */
    suspend fun decryptForChannel(channelId: String, content: String): String {
        val envelope = parseEnvelope(content) ?: return content
        val key = keyForEpoch(channelId, envelope.epoch) ?: return UNDECRYPTABLE
        return runCatching { Crypto.decrypt(envelope.ct, envelope.iv, key) }
            .getOrDefault(UNDECRYPTABLE)
    }

    suspend fun encryptFileForChannel(channelId: String, plaintext: ByteArray): Pair<Crypto.Sealed, Int> {
        val state = ensureChannelKey(channelId)
        val key = state.keys[state.epoch] ?: throw MissingChannelKeyError()
        return Crypto.encryptBytes(plaintext, key) to state.epoch
    }

    suspend fun decryptFileForChannel(
        channelId: String,
        ciphertext: ByteArray,
        iv: String,
        epoch: Int,
    ): ByteArray {
        val key = keyForEpoch(channelId, epoch) ?: throw MissingChannelKeyError()
        return Crypto.decryptBytes(ciphertext, iv, key)
    }

    /**
     * The key a call's DTLS fingerprint is signed with. It is the channel key,
     * which the server has never held - which is exactly why a signature made
     * with it proves the relay did not substitute a fingerprint of its own.
     */
    suspend fun callKeyForChannel(channelId: String, refresh: Boolean = false): String {
        // `refresh` is what a call asks for when somebody new arrives. Joining a
        // channel you hold no key for mints the next epoch - that is the only
        // way a new member gets one - so the newcomer's key is a generation
        // ahead of the one everybody already in the call read when they joined,
        // and without the re-read the two sides sign fingerprints with
        // different keys and refuse each other for good.
        if (refresh) forgetKeys(channelId)
        val state = ensureChannelKey(channelId)
        return state.keys[state.epoch] ?: throw MissingChannelKeyError()
    }


    // --- statuses ---
    //
    // A status has no channel, so it has no epoch and nothing to rotate: one
    // key per post, wrapped once per device that may read it, and gone in a
    // day. None of the channel machinery above applies - there is no state to
    // load, no gap to fill and no rekey.
    //
    // The wrap list is the audience, built from the directory at the moment of
    // posting. A friendship made afterwards adds nothing to a post already
    // written, which is why a new friend does not see yesterday's moment.

    /** A post, sealed and ready to send. */
    class SealedStatus(
        val caption: String?,
        val media: Crypto.Sealed?,
        val keys: List<StatusKeyEntry>,
        val senderDeviceId: String,
    )

    /**
     * Seals one post for one audience.
     *
     * This phone may not be in the directory yet - one that signed in a moment
     * ago has not been listed - so we always wrap for ourselves. Posting
     * something we cannot open is the one failure with no way back.
     */
    suspend fun sealStatus(
        caption: String?,
        media: ByteArray?,
        devices: List<DeviceKey>,
    ): SealedStatus {
        val self = currentIdentity()
        val key = Crypto.generateChannelKey()
        val mine = DeviceIdentity.id()
        val recipients = if (devices.any { it.userId == userId && it.deviceId == mine }) {
            devices
        } else {
            devices + DeviceKey(userId.orEmpty(), mine, self.publicKey)
        }

        val keys = recipients.mapNotNull { device ->
            runCatching {
                val wrapped = Crypto.wrapChannelKey(key, self.privateKey, device.publicKey)
                StatusKeyEntry(
                    recipientUserId = device.userId,
                    recipientDeviceId = device.deviceId,
                    senderPublicKey = self.publicKey,
                    wrappedKey = wrapped.wrappedKey,
                    iv = wrapped.iv,
                )
            }.getOrNull()
            // A directory row with a malformed public key must not stop the
            // post being sealed for everybody else.
        }

        // Epoch 0 in the envelope: a status has no generations, and the field
        // is there because the shape is shared with messages.
        val sealedCaption = caption?.takeIf { it.isNotBlank() }?.let {
            val sealed = Crypto.encrypt(it, key)
            JSONObject()
                .put("v", 1)
                .put("epoch", 0)
                .put("iv", sealed.iv)
                .put("ct", Crypto.base64(sealed.ciphertext))
                .toString()
        }
        return SealedStatus(
            caption = sealedCaption,
            media = media?.let { Crypto.encryptBytes(it, key) },
            keys = keys,
            senderDeviceId = mine,
        )
    }

    /**
     * The key to one post, from whichever wrap this phone's private half opens.
     *
     * Null rather than a throw for the ordinary cases: a post written before
     * this device existed, or before the friendship did, carries no wrap for
     * us. Both happen, and neither is an error.
     */
    suspend fun statusKey(post: StatusEntry): String? {
        if (post.keys.isEmpty()) return null
        val self = currentIdentity()
        for (wrap in post.keys) {
            val opened = runCatching {
                Crypto.unwrapChannelKey(
                    Crypto.Wrapped(wrap.wrappedKey, wrap.iv),
                    self.privateKey,
                    wrap.senderPublicKey,
                )
            }.getOrNull()
            if (opened != null) return opened
        }
        return null
    }

    /** A post's caption in the clear, or the placeholder. Never throws. */
    suspend fun openStatusCaption(post: StatusEntry): String? {
        val caption = post.caption ?: return null
        // Written before statuses were sealed. It expires within the day.
        val envelope = parseEnvelope(caption) ?: return caption
        val key = statusKey(post) ?: return UNDECRYPTABLE
        return runCatching { Crypto.decrypt(envelope.ct, envelope.iv, key) }
            .getOrDefault(UNDECRYPTABLE)
    }

    /** A post's media in the clear. Null when this device holds no key for it. */
    suspend fun openStatusMedia(post: StatusEntry, ciphertext: ByteArray): ByteArray? {
        // No IV means it was stored in the clear, before this. Hand it back.
        val iv = post.mediaIv ?: return ciphertext
        val key = statusKey(post) ?: return null
        return runCatching { Crypto.decryptBytes(ciphertext, iv, key) }.getOrNull()
    }

    private class Envelope(val epoch: Int, val iv: String, val ct: String)

    private fun parseEnvelope(content: String): Envelope? {
        if (!content.startsWith("{")) return null
        return runCatching {
            val json = JSONObject(content)
            if (json.optInt("v") != 1) return null
            val iv = json.optString("iv")
            val ct = json.optString("ct")
            if (iv.isEmpty() || ct.isEmpty() || !json.has("epoch")) return null
            Envelope(json.getInt("epoch"), iv, ct)
        }.getOrNull()
    }

    // --- channel keys ---

    /**
     * Re-wraps the current key for members who have none. Called when a channel
     * is opened, so somebody who joined after the key was minted becomes able to
     * read without anyone restarting the app.
     */
    suspend fun syncChannelKeys(channelId: String) {
        val state = runCatching { ensureChannelKey(channelId) }.getOrNull() ?: return
        val latest = BetweenUsApi.channelKeys(channelId)

        // Held state now survives a restart, so it can be days rather than
        // minutes behind. A different epoch means somebody re-keyed the channel
        // while this device was closed: ours is stale and theirs is the one
        // that counts. Without this the client would go on sealing under a dead
        // epoch until something else happened to invalidate it.
        if (latest.epoch != state.epoch) {
            forgetKeys(channelId)
            runCatching { ensureChannelKey(channelId) }
            return
        }

        fillGaps(channelId, state, latest)
    }

    /**
     * Hands every epoch this phone holds to the machines that are missing it.
     *
     * This is what lets a second machine read *history* rather than only what
     * is written after it arrives. Re-wrapping the current epoch and nothing
     * else left a machine that signed in today missing every epoch before
     * today - it holds none of them so it cannot repair itself, and with nobody
     * looking on its behalf it minted a fresh epoch and the whole conversation
     * before that moment stayed a padlock for good.
     *
     * The server only ever lists a machine whose *owner* already holds that
     * epoch, so this repairs one person's own second machine and hands nothing
     * to somebody who joined last week.
     *
     * Failures are per epoch and never fatal: a racing rotation or a device
     * revoked between the read and the write fails one wrap, and neither is a
     * reason to stop opening the channel.
     */
    private suspend fun fillGaps(channelId: String, state: ChannelKeyState, latest: ChannelKeys) {
        // Belt and braces for a server older than `gaps`, where this is the
        // only re-wrap that happens.
        state.keys[state.epoch]?.let { key ->
            if (latest.missingRecipients.isNotEmpty()) {
                runCatching { shareKey(channelId, state.epoch, key, latest.missingRecipients) }
            }
        }

        for (gap in latest.gaps) {
            // An epoch we cannot open is not ours to hand out, and the server
            // would refuse it anyway: only a holder may add to an existing one.
            val key = state.keys[gap.epoch] ?: continue
            if (gap.devices.isEmpty()) continue
            runCatching { shareKey(channelId, gap.epoch, key, gap.devices) }
        }
    }

    /** Keys a channel that was just created, so whoever opens it first can read. */
    suspend fun keyChannel(channelId: String) {
        runCatching { ensureChannelKey(channelId) }
    }

    private suspend fun keyForEpoch(channelId: String, epoch: Int): String? {
        channels[channelId]?.keys?.get(epoch)?.let { return it }
        runCatching { ensureChannelKey(channelId) }.getOrNull()?.keys?.get(epoch)?.let { return it }

        // An epoch we hold nothing for, on a channel we have already loaded.
        // Somebody re-keyed it while we were holding the old one - which is
        // exactly what a member who joined after the key was minted does, since
        // waiting for a re-wrap is not a fix - and our cached state is behind.
        //
        // Without re-reading here, the two clients sit on different epochs
        // until one of them is restarted: each renders the other's messages as
        // "no key on this device", and each keeps *sending* under its own stale
        // epoch so the reply is unreadable too. Reloading also moves this
        // client onto the newer epoch, which is what makes the conversation
        // work in both directions again.
        if (!missedEpochs.add("$channelId#$epoch")) return null
        forgetKeys(channelId)

        val fresh = runCatching { ensureChannelKey(channelId) }.getOrNull()?.keys?.get(epoch)
        // It was there after all, so anything else given up on for this channel
        // deserves another go.
        if (fresh != null) missedEpochs.removeAll { it.startsWith("$channelId#") }
        return fresh
    }

    /**
     * Resolves the channel's key, creating and distributing one if the channel
     * has never been keyed. Concurrent callers share one round trip.
     */
    private suspend fun ensureChannelKey(channelId: String): ChannelKeyState {
        channels[channelId]?.let { return it }
        val lock = channelLocks.getOrPut(channelId) { Mutex() }
        return lock.withLock {
            channels[channelId]
                ?: recallKeys(channelId)?.also { channels[channelId] = it }
                ?: loadChannelKey(channelId).also {
                    channels[channelId] = it
                    rememberKeys(channelId, it)
                }
        }
    }

    // --- channel keys at rest ---
    //
    // Without these, the message cache is useless: every cached row is an
    // envelope, and opening one meant a round trip to the key directory first.
    // A conversation would come back off disk instantly and then sit there
    // saying it had no key until the network answered - and say it for good
    // when there was no network to answer.
    //
    // They go in the same Keystore-sealed store the identity does, and not in
    // the cache database, which is deliberately worth nothing on its own.

    private fun keyStorageKey(channelId: String): String? =
        userId?.let { "channelkeys:$it:$channelId" }

    private fun rememberKeys(channelId: String, state: ChannelKeyState) {
        val name = keyStorageKey(channelId) ?: return
        runCatching {
            val keys = JSONObject()
            state.keys.forEach { (epoch, key) -> keys.put(epoch.toString(), key) }
            store.put(name, JSONObject().put("epoch", state.epoch).put("keys", keys).toString())
        }
    }

    private fun recallKeys(channelId: String): ChannelKeyState? {
        val name = keyStorageKey(channelId) ?: return null
        return runCatching {
            val json = JSONObject(store.get(name) ?: return null)
            val keys = json.getJSONObject("keys")
            ChannelKeyState(
                epoch = json.getInt("epoch"),
                keys = keys.keys().asSequence().associate { it.toInt() to keys.getString(it) },
            )
        }.getOrNull()
    }

    /** Drops a channel's keys from memory and from disk, so the next read refetches. */
    private fun forgetKeys(channelId: String) {
        channels.remove(channelId)
        keyStorageKey(channelId)?.let { runCatching { store.remove(it) } }
    }

    /**
     * Drops every channel key this device holds, in memory and at rest.
     *
     * Called when the identity changes under it - [restoreFromBackup]. The keys
     * are still valid, but they are the *subset* the old identity could reach,
     * and both caches would go on serving that subset while the wraps the new
     * identity can open sat unread in the directory.
     */
    private fun forgetAllKeys() {
        channels.clear()
        rekeyed.clear()
        missedEpochs.clear()
        userId?.let { runCatching { store.removeByPrefix("channelkeys:$it:") } }
    }

    private suspend fun loadChannelKey(channelId: String): ChannelKeyState {
        val self = currentIdentity()
        var response = BetweenUsApi.channelKeys(channelId)
        var keys = openKeys(response.keys, self)

        // We hold nothing for the current epoch. Either nobody has keyed the
        // channel yet, or it was keyed before we joined and every holder who
        // could re-wrap it for us is offline. Waiting on them is not a fix, so
        // mint the next epoch and wrap it for everybody - which is exactly what
        // the server lets any member who may send a message do. Earlier epochs
        // are untouched, so history from before we were a member stays closed.
        if (!keys.containsKey(response.epoch) && rekeyed.add(channelId)) {
            createChannelKey(channelId, response.epoch + 1)
            // Re-read rather than trusting our own write: another member may
            // have won the race, and then theirs is the epoch that counts.
            response = BetweenUsApi.channelKeys(channelId)
            keys = openKeys(response.keys, self)
        }

        if (!keys.containsKey(response.epoch)) throw MissingChannelKeyError()

        // Members who joined after the key was minted cannot read anything
        // until a holder re-wraps it for them. We hold it, so we do it.
        if (response.missingRecipients.isNotEmpty()) {
            keys[response.epoch]?.let {
                runCatching { shareKey(channelId, response.epoch, it, response.missingRecipients) }
            }
        }

        return ChannelKeyState(response.epoch, keys)
    }

    /** Opens every entry sealed for us, keyed by epoch. */
    private fun openKeys(
        entries: List<ChannelKeyEntry>,
        self: Crypto.KeyPairJwk,
    ): MutableMap<Int, String> {
        val keys = mutableMapOf<Int, String>()
        for (entry in entries) {
            runCatching {
                keys[entry.epoch] = Crypto.unwrapChannelKey(
                    Crypto.Wrapped(entry.wrappedKey, entry.iv),
                    self.privateKey,
                    entry.senderPublicKey,
                )
            }
            // A key sealed for another of our machines, or for an identity we
            // have since replaced. Both are rows this private half cannot open.
        }
        return keys
    }

    /**
     * Mints an epoch for a channel this device holds no key for - one nobody has
     * keyed, or one that was keyed before we were a member.
     */
    private suspend fun createChannelKey(channelId: String, epoch: Int) {
        val self = currentIdentity()
        val key = Crypto.generateChannelKey()
        val devices = BetweenUsApi.channelDevices(channelId)

        // Our own row may not be in the directory yet on a device that signed in
        // a moment ago. Minting a key we cannot open - or, with an empty
        // directory, publishing nothing at all - leaves the channel unkeyed and
        // the sender told there is no key, so always seal one for ourselves.
        // Being listed under our user id is no longer enough: the directory is a
        // row per machine, and that row may be the other laptop.
        val mine = DeviceIdentity.id()
        val recipients = if (devices.any { it.userId == userId && it.deviceId == mine }) {
            devices
        } else {
            devices + DeviceKey(userId.orEmpty(), mine, self.publicKey)
        }

        try {
            shareKey(channelId, epoch, key, recipients)
        } catch (error: ApiError) {
            // Another member keyed it first: harmless, the caller re-reads and
            // finds theirs. Which code comes back depends on whether they landed
            // on the epoch we wanted or ran past it. Anything else is a real
            // failure and must not be mistaken for "this device has no key".
            val raced = error.code == "EPOCH_OUT_OF_ORDER" || error.code == "EPOCH_NOT_HELD"
            if (!raced) throw error
        }
    }

    private suspend fun shareKey(
        channelId: String,
        epoch: Int,
        key: String,
        recipients: List<DeviceKey>,
    ) {
        if (recipients.isEmpty()) return
        val self = currentIdentity()
        val entries = recipients.mapNotNull { recipient ->
            runCatching {
                val wrapped = Crypto.wrapChannelKey(key, self.privateKey, recipient.publicKey)
                ChannelKeyEntry(
                    recipientUserId = recipient.userId,
                    recipientDeviceId = recipient.deviceId,
                    senderUserId = userId.orEmpty(),
                    senderDeviceId = DeviceIdentity.id(),
                    senderPublicKey = self.publicKey,
                    wrappedKey = wrapped.wrappedKey,
                    iv = wrapped.iv,
                    epoch = epoch,
                )
            }.getOrNull()
            // A directory row with a malformed public key must not stop the
            // channel being keyed for everybody else.
        }
        if (entries.isEmpty()) return
        BetweenUsApi.publishChannelKeys(channelId, epoch, DeviceIdentity.id(), entries)
    }
}

package com.aatech.betweenus.core.crypto

import android.content.Context
import android.content.SharedPreferences
import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import java.security.KeyStore
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec
import android.util.Base64

/**
 * Where private key material is kept at rest.
 *
 * The desktop client hands identity keys to its main process, which seals them
 * with the OS keychain. This is the same idea with the parts Android has: an
 * AES key generated *inside* the hardware-backed keystore - it cannot be
 * exported, only used - wrapping the value that then sits in ordinary
 * preferences. A rooted device can read the preferences file and get
 * ciphertext; opening it means asking the keystore, which means being this app
 * on this device.
 *
 * Deliberately no user authentication requirement on the key: a channel key has
 * to be openable to render a message list, and prompting for a fingerprint per
 * message is not a product. Locking the identity behind biometrics is a setting
 * worth having later, not a default that would make the app unusable.
 */
class SecureStore(context: Context) {
    private val prefs: SharedPreferences =
        context.applicationContext.getSharedPreferences("betweenus.secure", Context.MODE_PRIVATE)

    private val keyStore = KeyStore.getInstance(KEYSTORE).apply { load(null) }

    fun get(name: String): String? {
        val stored = prefs.getString(name, null) ?: return null
        val separator = stored.indexOf(':')
        if (separator <= 0) return null
        return runCatching {
            val iv = Base64.decode(stored.substring(0, separator), Base64.NO_WRAP)
            val ciphertext = Base64.decode(stored.substring(separator + 1), Base64.NO_WRAP)
            val cipher = Cipher.getInstance(TRANSFORMATION)
            cipher.init(Cipher.DECRYPT_MODE, secretKey(), GCMParameterSpec(128, iv))
            String(cipher.doFinal(ciphertext))
        }.getOrNull()
        // A null here means the wrapping key is gone - the app was reinstalled,
        // or the user reset their screen lock on an older device. The identity
        // is then recovered from the account backup, which is what it is for.
    }

    fun put(name: String, value: String) {
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.ENCRYPT_MODE, secretKey())
        val ciphertext = cipher.doFinal(value.toByteArray())
        val encoded = Base64.encodeToString(cipher.iv, Base64.NO_WRAP) + ":" +
            Base64.encodeToString(ciphertext, Base64.NO_WRAP)
        prefs.edit().putString(name, encoded).apply()
    }

    fun remove(name: String) {
        prefs.edit().remove(name).apply()
    }

    /**
     * Drops every entry whose name starts with [prefix].
     *
     * What "forget the channel keys this identity could reach" is made of. The
     * names carry the user id and channel id, so a prefix is the only way to
     * name a set of them without keeping a second index of what was written.
     */
    fun removeByPrefix(prefix: String) {
        val editor = prefs.edit()
        prefs.all.keys.filter { it.startsWith(prefix) }.forEach { editor.remove(it) }
        editor.apply()
    }

    private fun secretKey(): SecretKey {
        (keyStore.getEntry(KEY_ALIAS, null) as? KeyStore.SecretKeyEntry)?.let { return it.secretKey }

        val generator = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, KEYSTORE)
        generator.init(
            KeyGenParameterSpec.Builder(
                KEY_ALIAS,
                KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT,
            )
                .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
                .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
                .build(),
        )
        return generator.generateKey()
    }

    private companion object {
        const val KEYSTORE = "AndroidKeyStore"
        const val KEY_ALIAS = "betweenus.identity.wrap"
        const val TRANSFORMATION = "AES/GCM/NoPadding"
    }
}

