    document.getElementById('returnBtn').onclick = (e) => { e.stopPropagation(); openBetweenUs(); };
    document.getElementById('micBtn').onclick = (e) => { e.stopPropagation(); ipcRenderer.send('pip:action', { type: 'toggleMic' }); };
